CREATE OR REPLACE FUNCTION public."B36_execution_binding"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r "OwnerReportRun"; root_xid xid;
BEGIN
 IF TG_OP = 'UPDATE' THEN
  IF (NEW."ownerReportRunId",NEW."ownerReportSlotKey") IS DISTINCT FROM
     (OLD."ownerReportRunId",OLD."ownerReportSlotKey") THEN
   RAISE EXCEPTION 'B36 execution binding immutable; historical promotion forbidden' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF OLD."ownerReportRunId" IS NOT NULL AND EXISTS (
   SELECT 1 FROM "OwnerReportRun" WHERE id=OLD."ownerReportRunId" AND "auditRetentionUntil">clock_timestamp()
  ) THEN RAISE EXCEPTION 'B36 durable execution retention' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF NEW."ownerReportRunId" IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO r FROM "OwnerReportRun" WHERE id=NEW."ownerReportRunId" AND "tenantId"=NEW."tenantId";
 SELECT xmin INTO root_xid FROM "OwnerReportRun" WHERE id=NEW."ownerReportRunId" AND "tenantId"=NEW."tenantId";
 -- New slots can only join the transaction that first inserts the immutable root.
 IF r.id IS NULL OR root_xid IS DISTINCT FROM pg_current_xact_id()::xid
  OR r."intentEncrypted" IS NULL OR NEW.state <> 'READY'
  OR NEW."intentExpiresAt" IS DISTINCT FROM r."expiresAt"
  OR NEW."dryRun" OR NEW."policyDecision" <> 'ALLOW' THEN
  RAISE EXCEPTION 'B36 atomic accepted report admission required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."B36_report_immutable"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'INSERT' THEN
  IF NEW."intentEncrypted" IS NULL OR length(NEW."intentEncrypted") = 0 THEN
   RAISE EXCEPTION 'B36 recoverable immutable plan required' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF OLD."auditRetentionUntil" > clock_timestamp() THEN
   RAISE EXCEPTION 'B36 report identity retention' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW."intentEncrypted" IS NULL AND OLD."intentEncrypted" IS NOT NULL
  AND OLD."payloadRetentionUntil" <= clock_timestamp()
  AND (to_jsonb(NEW) - 'intentEncrypted') = (to_jsonb(OLD) - 'intentEncrypted') THEN
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'B36 immutable report identity/manifest' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R06_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "OperationalAlertRun"%ROWTYPE; root_xid xid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."operationalAlertRunId" IS NOT NULL THEN RAISE EXCEPTION 'R06 slot tombstone retained' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."operationalAlertRunId" IS DISTINCT FROM OLD."operationalAlertRunId" OR NEW."operationalAlertSlotKey" IS DISTINCT FROM OLD."operationalAlertSlotKey" THEN
   RAISE EXCEPTION 'R06 immutable slot binding' USING ERRCODE='23514';
  END IF; RETURN NEW;
 END IF;
 IF NEW."operationalAlertRunId" IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO root FROM "OperationalAlertRun" WHERE id=NEW."operationalAlertRunId" AND "tenantId"=NEW."tenantId";
 SELECT xmin INTO root_xid FROM "OperationalAlertRun" WHERE id=root.id;
 IF root.id IS NULL OR root_xid<>pg_current_xact_id()::xid OR root."intentEncrypted" IS NULL OR NEW.state<>'READY'
  OR NEW."policyDecision"<>'ALLOW' OR NEW."dryRun" OR NEW."intentExpiresAt" IS DISTINCT FROM root."expiresAt"
  OR (root."alertType"='staff_shift_reminder' AND (NEW.capability<>'communication.appointment-reminders.execute.v1' OR NEW."actionClass"<>'deliver_appointment_reminder'))
  OR (root."alertType"='wanted_slot_admin_notice' AND (NEW.capability<>'communication.business-alerts.execute.v1' OR NEW."actionClass"<>'deliver_business_alert')) THEN
  RAISE EXCEPTION 'R06 exact type / complete same-transaction admission required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R08_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_execution text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."nativeFeedbackRequestId" IS NOT NULL THEN RAISE EXCEPTION 'R08 delivery evidence retained' USING ERRCODE='23514'; END IF; RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."nativeFeedbackRequestId" IS DISTINCT FROM OLD."nativeFeedbackRequestId" OR NEW."nativeFeedbackRevisionId" IS DISTINCT FROM OLD."nativeFeedbackRevisionId" OR NEW."nativeFeedbackSlotKey" IS DISTINCT FROM OLD."nativeFeedbackSlotKey" THEN RAISE EXCEPTION 'R08 immutable delivery slot binding' USING ERRCODE='23514'; END IF; RETURN NEW;
 END IF;
 IF NEW."nativeFeedbackRequestId" IS NULL THEN RETURN NEW; END IF;
 IF NEW."nativeFeedbackRevisionId" IS NULL THEN
  SELECT "requestExecutionId" INTO parent_execution FROM "NativeFeedbackRequest" WHERE id=NEW."nativeFeedbackRequestId" AND "tenantId"=NEW."tenantId" AND "planEncrypted" IS NOT NULL;
 ELSE
  SELECT "executionId" INTO parent_execution FROM "NativeFeedbackRevision" WHERE id=NEW."nativeFeedbackRevisionId" AND "tenantId"=NEW."tenantId" AND "requestId"=NEW."nativeFeedbackRequestId" AND "planEncrypted" IS NOT NULL AND kind='response';
 END IF;
 IF parent_execution IS NULL OR NEW.state<>'READY' OR NEW."dryRun" OR NEW."policyDecision"<>'ALLOW' OR NOT EXISTS (SELECT 1 FROM "ActionExecution" WHERE id=parent_execution AND "tenantId"=NEW."tenantId" AND state='SUCCEEDED') THEN
  RAISE EXCEPTION 'R08 confirmed parent and complete slot admission required' USING ERRCODE='23514';
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R08_revision_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "NativeFeedbackRequest"%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R08 response tombstone retained' USING ERRCODE='23514'; END IF;
 SELECT * INTO root FROM "NativeFeedbackRequest" WHERE id=NEW."requestId" AND "tenantId"=NEW."tenantId" FOR UPDATE;
 IF TG_OP='INSERT' THEN
  IF root.id IS NULL OR root."clientId"<>NEW."clientId" OR NEW.version<>root."latestResponseVersion"+1
   OR (NEW.kind='response' AND NEW."createdAt">root."expiresAt") OR NEW."planEncrypted" IS NULL OR NEW."payloadErasedAt" IS NOT NULL
   OR NOT EXISTS (SELECT 1 FROM "ActionExecution" e WHERE e.id=NEW."executionId" AND e."tenantId"=NEW."tenantId" AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
    AND e."actionClass"=CASE WHEN NEW.kind='withdraw' THEN 'withdraw_native_feedback' ELSE 'submit_native_feedback_revision' END)
   OR NOT EXISTS (SELECT 1 FROM "ActionExecution" WHERE id=root."requestExecutionId" AND "tenantId"=root."tenantId" AND state='SUCCEEDED') THEN
   RAISE EXCEPTION 'R08 exact admitted Client response / current revision required' USING ERRCODE='23514';
  END IF; RETURN NEW;
 END IF;
 IF NEW."commentEncrypted" IS NULL AND NEW."planEncrypted" IS NULL AND OLD."payloadErasedAt" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND (to_jsonb(NEW)-ARRAY['commentEncrypted','planEncrypted','payloadErasedAt'])=(to_jsonb(OLD)-ARRAY['commentEncrypted','planEncrypted','payloadErasedAt'])
  AND "RC_payload_claim"(OLD."tenantId",'NativeFeedbackRevision',OLD.id,OLD."planHash",root."retentionUntil",'purge_native_feedback_payloads','native-feedback-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY(SELECT id FROM "ActionExecution" WHERE "tenantId"=OLD."tenantId" AND (id=OLD."executionId" OR "nativeFeedbackRevisionId"=OLD.id))) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R08 immutable response / exact payload claim required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R08_revision_projection_receipt"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "NativeFeedbackRequest"%ROWTYPE; latest "NativeFeedbackRevision"%ROWTYPE;
BEGIN
 SELECT * INTO root FROM "NativeFeedbackRequest" WHERE id=NEW."requestId" AND "tenantId"=NEW."tenantId";
 SELECT * INTO latest FROM "NativeFeedbackRevision" WHERE "requestId"=NEW."requestId" AND "tenantId"=NEW."tenantId" ORDER BY version DESC LIMIT 1;
 IF root."latestResponseVersion"<>latest.version OR root.revision<>latest.version OR
  root.state<>(CASE WHEN latest.kind='withdraw' THEN 'WITHDRAWN' ELSE 'RESPONDED' END) THEN
  RAISE EXCEPTION 'R08 accepted revision and exact current projection must commit together' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R09_comment_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE ref text; parent "PublicCommunityComment"%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R09 source and moderation tombstones retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW."authorEncrypted" IS NULL OR NEW."textEncrypted" IS NULL OR NEW."payloadErasedAt" IS NOT NULL OR NEW.revision<>0 THEN
   RAISE EXCEPTION 'R09 immutable initial content required' USING ERRCODE='23514';
  END IF;
  IF NEW."sourceKind"='GUEST' THEN
   IF NEW.status<>'PENDING' OR NEW."lastModerationExecutionId" IS NOT NULL THEN RAISE EXCEPTION 'R09 guest source cannot publish itself' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT * INTO parent FROM "PublicCommunityComment" WHERE id=NEW."parentCommentId" AND "tenantId"=NEW."tenantId" FOR SHARE;
   IF parent.id IS NULL OR parent.status<>'APPROVED' OR parent."publicationKey"<>NEW."publicationKey" OR NEW.status<>'APPROVED' THEN
    RAISE EXCEPTION 'R09 reply exact approved parent required' USING ERRCODE='23514';
   END IF;
   ref=NEW."creationExecutionId";
  END IF;
 ELSIF NEW."authorEncrypted" IS NULL AND NEW."textEncrypted" IS NULL AND OLD."payloadErasedAt" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND (to_jsonb(NEW)-ARRAY['authorEncrypted','textEncrypted','payloadErasedAt'])=(to_jsonb(OLD)-ARRAY['authorEncrypted','textEncrypted','payloadErasedAt'])
  AND "RC_payload_claim"(OLD."tenantId",'PublicCommunityComment',OLD.id,OLD."contentHash",OLD."retentionUntil",'purge_public_community_payloads','public-community-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY_REMOVE(ARRAY[OLD."creationExecutionId",OLD."lastModerationExecutionId"],NULL)) THEN RETURN NEW;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','revision','lastModerationExecutionId'])<>(to_jsonb(OLD)-ARRAY['status','revision','lastModerationExecutionId'])
   OR NEW.revision<>OLD.revision+1 OR NEW."lastModerationExecutionId" IS NULL OR NEW."lastModerationExecutionId" IS NOT DISTINCT FROM OLD."lastModerationExecutionId" THEN
   RAISE EXCEPTION 'R09 immutable content / explicit moderation CAS required' USING ERRCODE='23514';
  END IF;
  ref=NEW."lastModerationExecutionId";
 END IF;
 IF ref IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
  WHERE e.id=ref AND e."tenantId"=NEW."tenantId" AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
   AND e."actionClass"=CASE WHEN TG_OP='INSERT' THEN 'publish_public_community_reply' ELSE 'moderate_public_community_comment' END
   AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator')) THEN
  RAISE EXCEPTION 'R09 exact human moderator execution required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R09_interaction_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'R09 immutable anonymous source fact' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('r09/'||NEW."tenantId"||'/'||NEW."sourceGatewayId"||'/'||NEW."publicationKey"||'/'||NEW."visitorSubjectHash"||'/'||NEW.kind,0));
 SELECT COALESCE(max(version),0) INTO previous FROM "PublicCommunityInteraction" WHERE "tenantId"=NEW."tenantId" AND "sourceGatewayId"=NEW."sourceGatewayId" AND "publicationKey"=NEW."publicationKey" AND "visitorSubjectHash"=NEW."visitorSubjectHash" AND kind=NEW.kind;
 IF NEW."expectedVersion"<>previous THEN RAISE EXCEPTION 'R09 stale source projection version' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R11_config_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous "TenantBusinessConfigurationRevision"%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW."encryptedContent" IS NULL OR length(NEW."encryptedContent")=0 OR NOT EXISTS (
   SELECT 1 FROM "Membership" m JOIN "User" u ON u.id=m."userId" JOIN "ActionExecution" e ON e.id=NEW."actionExecutionId" AND e."tenantId"=NEW."tenantId"
   WHERE m.id=NEW."actorMembershipId" AND m."tenantId"=NEW."tenantId" AND m."userId"=NEW."actorUserId"
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner')
    AND e."actorUserId"=NEW."actorUserId" AND e."actionClass"='update_tenant_business_configuration'
    AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW') THEN
   RAISE EXCEPTION 'R11 exact admitted actor/configuration required' USING ERRCODE='23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('r11/'||NEW."tenantId"||'/'||NEW.namespace,0));
  SELECT * INTO previous FROM "TenantBusinessConfigurationRevision" WHERE "tenantId"=NEW."tenantId" AND namespace=NEW.namespace ORDER BY revision DESC LIMIT 1;
  IF (previous.id IS NULL AND (NEW.revision<>1 OR NEW."previousRevisionId" IS NOT NULL)) OR
    (previous.id IS NOT NULL AND (NEW."previousRevisionId" IS DISTINCT FROM previous.id OR NEW.revision<>previous.revision+1)) THEN
   RAISE EXCEPTION 'R11 stale namespace predecessor' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD."encryptedContent" IS NOT NULL AND NEW."encryptedContent" IS NULL
  AND (to_jsonb(NEW)-'encryptedContent')=(to_jsonb(OLD)-'encryptedContent')
  AND EXISTS (SELECT 1 FROM "TenantBusinessConfigurationRevision" r WHERE r."tenantId"=OLD."tenantId" AND r.namespace=OLD.namespace AND r.revision>OLD.revision)
  AND "RC_payload_claim"(OLD."tenantId",'TenantBusinessConfigurationRevision',OLD.id,OLD."contentHash",OLD."createdAt"+interval '365 days','purge_superseded_business_configuration_payloads','package5.r11.business-configuration-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY[OLD."actionExecutionId"])
 THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R11 append-only configuration / scoped superseded payload claim required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R12_attachment_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE exec text; msg "TeamMessage"%ROWTYPE; deadline timestamptz;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R12 attachment tombstone retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'RESERVED' OR NEW.revision<>0 OR NEW."finalizeExecutionId" IS NOT NULL OR NEW."actualSize" IS NOT NULL OR NEW."storageReceiptHash" IS NOT NULL OR NEW."mediaExpiresAt" IS NOT NULL OR NEW."payloadErasedAt" IS NOT NULL OR NEW."filenameEncrypted" IS NULL THEN RAISE EXCEPTION 'R12 reservation before publish required' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
   WHERE e.id=NEW."reserveExecutionId" AND e."tenantId"=NEW."tenantId" AND e."actorUserId"=NEW."ownerUserId" AND e."actionClass"='reserve_team_attachment' AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator','staff')) THEN RAISE EXCEPTION 'R12 canonical current reservation owner required' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['finalizeExecutionId','actualSize','state','revision','mediaExpiresAt','storageReceiptHash','payloadErasedAt','lastObservedAt','filenameEncrypted'])<>(to_jsonb(OLD)-ARRAY['finalizeExecutionId','actualSize','state','revision','mediaExpiresAt','storageReceiptHash','payloadErasedAt','lastObservedAt','filenameEncrypted'])
  OR NEW.revision<>OLD.revision+1 OR (OLD."finalizeExecutionId" IS NOT NULL AND NEW."finalizeExecutionId" IS DISTINCT FROM OLD."finalizeExecutionId") THEN RAISE EXCEPTION 'R12 immutable upload intent / CAS required' USING ERRCODE='23514'; END IF;
 SELECT * INTO msg FROM "TeamMessage" WHERE "attachmentId"=OLD.id AND "tenantId"=OLD."tenantId";
 deadline=CASE WHEN msg.id IS NULL THEN OLD."uploadExpiresAt" ELSE LEAST(msg."createdAt"+interval '48 hours',COALESCE(msg."withdrawnAt",msg."createdAt"+interval '48 hours')) END;
 IF NEW.state='ERASED' AND OLD.state<>'ERASED' AND NEW."filenameEncrypted" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND NEW."actualSize" IS NOT DISTINCT FROM OLD."actualSize" AND NEW."mediaExpiresAt" IS NOT DISTINCT FROM OLD."mediaExpiresAt" AND NEW."storageReceiptHash" IS NOT DISTINCT FROM OLD."storageReceiptHash"
  AND "RC_payload_claim"(OLD."tenantId",'TeamAttachment',OLD.id,OLD."contentSha256",deadline,'purge_team_attachment_payloads','team-lifecycle-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY(SELECT id FROM "ActionExecution" WHERE "tenantId"=OLD."tenantId" AND (id=OLD."reserveExecutionId" OR id=OLD."finalizeExecutionId" OR id=msg."sendExecutionId" OR id=msg."withdrawalExecutionId" OR "teamMessageId"=msg.id))) THEN RETURN NEW; END IF;
 IF NEW."filenameEncrypted" IS DISTINCT FROM OLD."filenameEncrypted" OR NEW."payloadErasedAt" IS DISTINCT FROM OLD."payloadErasedAt" THEN RAISE EXCEPTION 'R12 exact attachment payload claim required' USING ERRCODE='23514'; END IF;
 IF OLD.state='SEALED' AND NEW.state='BOUND' AND msg.id IS NOT NULL AND NEW."mediaExpiresAt"=msg."createdAt"+interval '48 hours'
  AND NEW."actualSize" IS NOT DISTINCT FROM OLD."actualSize" AND NEW."storageReceiptHash" IS NOT DISTINCT FROM OLD."storageReceiptHash"
  AND EXISTS (SELECT 1 FROM "TeamMessage" WHERE id=msg.id AND xmin=pg_current_xact_id()::xid) THEN RETURN NEW; END IF;
 IF OLD.state='RESERVED' AND NEW.state IN ('RESERVED','SEALED') AND NEW."finalizeExecutionId" IS NOT NULL AND NEW."mediaExpiresAt" IS NULL
  AND EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
   WHERE e.id=NEW."finalizeExecutionId" AND e."tenantId"=NEW."tenantId" AND e."actorUserId"=NEW."ownerUserId" AND e."actionClass"='finalize_team_attachment'
    AND e.state IN ('READY','EXECUTING','UNKNOWN','SUCCEEDED') AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator','staff')) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R12 canonical reservation/finalization/binding transition required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R12_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."teamMessageId" IS NOT NULL THEN RAISE EXCEPTION 'R12 delivery evidence retained' USING ERRCODE='23514'; END IF; RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."teamMessageId" IS DISTINCT FROM OLD."teamMessageId" OR NEW."teamMessageSlotKey" IS DISTINCT FROM OLD."teamMessageSlotKey" THEN RAISE EXCEPTION 'R12 immutable delivery slot binding' USING ERRCODE='23514'; END IF; RETURN NEW;
 END IF;
 IF NEW."teamMessageId" IS NULL THEN RETURN NEW; END IF;
 IF NEW.state<>'READY' OR NEW."dryRun" OR NEW."policyDecision"<>'ALLOW' OR NOT EXISTS (
  SELECT 1 FROM "TeamMessage" m JOIN "ActionExecution" e ON e.id=m."sendExecutionId" AND e."tenantId"=m."tenantId"
  WHERE m.id=NEW."teamMessageId" AND m."tenantId"=NEW."tenantId" AND m."planEncrypted" IS NOT NULL AND m.status='SENT' AND e.state='SUCCEEDED') THEN RAISE EXCEPTION 'R12 confirmed message and complete slot admission required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R12_message_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE exec text; class text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R12 message tombstone retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'SENT' OR NEW.revision<>0 OR NEW."payloadEncrypted" IS NULL OR NEW."planEncrypted" IS NULL OR NEW."payloadErasedAt" IS NOT NULL THEN RAISE EXCEPTION 'R12 initial immutable message plan required' USING ERRCODE='23514'; END IF;
  IF NEW."attachmentId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "TeamAttachment" a JOIN "ActionExecution" e ON e.id=a."finalizeExecutionId" AND e."tenantId"=a."tenantId"
   WHERE a.id=NEW."attachmentId" AND a."tenantId"=NEW."tenantId" AND a."ownerUserId"=NEW."senderUserId" AND a.state='SEALED' AND e.state='SUCCEEDED' AND a."payloadErasedAt" IS NULL) THEN RAISE EXCEPTION 'R12 exact finalized owned attachment required' USING ERRCODE='23514'; END IF;
  exec=NEW."sendExecutionId";class='send_team_message';
 ELSIF NEW."payloadEncrypted" IS NULL AND NEW."planEncrypted" IS NULL AND OLD."payloadErasedAt" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND (to_jsonb(NEW)-ARRAY['payloadEncrypted','planEncrypted','payloadErasedAt'])=(to_jsonb(OLD)-ARRAY['payloadEncrypted','planEncrypted','payloadErasedAt'])
  AND "RC_payload_claim"(OLD."tenantId",'TeamMessage',OLD.id,OLD."planHash",LEAST(OLD."expiresAt",COALESCE(OLD."withdrawnAt",OLD."expiresAt")),'purge_team_message_payloads','team-lifecycle-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY(SELECT id FROM "ActionExecution" WHERE "tenantId"=OLD."tenantId" AND (id=OLD."sendExecutionId" OR id=OLD."withdrawalExecutionId" OR "teamMessageId"=OLD.id))) THEN RETURN NEW;
 ELSE
  IF OLD.status<>'SENT' OR NEW.status<>'WITHDRAWN' OR NEW.revision<>OLD.revision+1
   OR (to_jsonb(NEW)-ARRAY['status','revision','withdrawnAt','withdrawnByUserId','withdrawalExecutionId','withdrawalIdentityHash','withdrawalIntentHash'])<>(to_jsonb(OLD)-ARRAY['status','revision','withdrawnAt','withdrawnByUserId','withdrawalExecutionId','withdrawalIdentityHash','withdrawalIntentHash']) THEN RAISE EXCEPTION 'R12 explicit own withdrawal only' USING ERRCODE='23514'; END IF;
  exec=NEW."withdrawalExecutionId";class='withdraw_team_message';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
  WHERE e.id=exec AND e."tenantId"=NEW."tenantId" AND e."actorUserId"=NEW."senderUserId" AND e."actionClass"=class
   AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW' AND m.status='active' AND u.status='active'
   AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator','staff')) THEN RAISE EXCEPTION 'R12 current admitted sender required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R13_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "ExpenseReminderRun"%ROWTYPE; root_xid xid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."expenseReminderRunId" IS NOT NULL THEN RAISE EXCEPTION 'R13 slot tombstone retained' USING ERRCODE='23514'; END IF; RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."expenseReminderRunId" IS DISTINCT FROM OLD."expenseReminderRunId" OR NEW."expenseReminderSlotKey" IS DISTINCT FROM OLD."expenseReminderSlotKey" THEN
   RAISE EXCEPTION 'R13 immutable slot binding' USING ERRCODE='23514';
  END IF; RETURN NEW;
 END IF;
 IF NEW."expenseReminderRunId" IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO root FROM "ExpenseReminderRun" WHERE id=NEW."expenseReminderRunId" AND "tenantId"=NEW."tenantId";
 SELECT xmin INTO root_xid FROM "ExpenseReminderRun" WHERE id=root.id;
 IF root.id IS NULL OR root_xid<>pg_current_xact_id()::xid OR root."intentEncrypted" IS NULL OR NEW.state<>'READY'
  OR NEW."policyDecision"<>'ALLOW' OR NEW."dryRun" OR NEW."intentExpiresAt" IS DISTINCT FROM (root."expiresAt" AT TIME ZONE 'UTC') THEN
  RAISE EXCEPTION 'R13 complete same-transaction weekly admission required' USING ERRCODE='23514';
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R13_intake_complete"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE n integer; lo integer; hi integer;
BEGIN
 SELECT count(*),min("itemIndex"),max("itemIndex") INTO n,lo,hi FROM "ExpenseIntakeBinding"
  WHERE "tenantId"=NEW."tenantId" AND "sourceNamespace"=NEW."sourceNamespace" AND "sourceEventHash"=NEW."sourceEventHash";
 IF n<>NEW."sourceItemCount" OR lo<>0 OR hi<>n-1 THEN RAISE EXCEPTION 'R13 full frozen card bundle required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R13_intake_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior "ExpenseIntakeBinding"%ROWTYPE; prior_xid xid; approval_xid xid;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'R13 source binding is immutable' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('r13-intake/'||NEW."tenantId"||'/'||NEW."sourceNamespace"||'/'||NEW."sourceEventHash",0));
 SELECT * INTO prior FROM "ExpenseIntakeBinding" WHERE "tenantId"=NEW."tenantId" AND "sourceNamespace"=NEW."sourceNamespace" AND "sourceEventHash"=NEW."sourceEventHash" LIMIT 1;
 IF prior.id IS NOT NULL THEN
  SELECT xmin INTO prior_xid FROM "ExpenseIntakeBinding" WHERE id=prior.id;
  IF prior_xid<>pg_current_xact_id()::xid OR
   (to_jsonb(prior)-ARRAY['id','itemIndex','approvalRequestId'])<>(to_jsonb(NEW)-ARRAY['id','itemIndex','approvalRequestId']) THEN
   RAISE EXCEPTION 'R13 no late append / conflicting source bundle' USING ERRCODE='23514';
  END IF;
 END IF;
 SELECT xmin INTO approval_xid FROM "AiApprovalRequest" WHERE id=NEW."approvalRequestId" AND "tenantId"=NEW."tenantId";
 IF approval_xid IS NULL OR approval_xid<>pg_current_xact_id()::xid OR NOT EXISTS (
  SELECT 1 FROM "Membership" m JOIN "User" u ON u.id=m."userId"
   JOIN "AuthIdentity" a ON a.id=NEW."authIdentityId" AND a."tenantId"=m."tenantId" AND a."userId"=m."userId" AND a.provider='telegram'
   JOIN "AiApprovalRequest" q ON q.id=NEW."approvalRequestId" AND q."tenantId"=m."tenantId" AND q."requestedByUserId"=m."userId"
  WHERE m.id=NEW."actorMembershipId" AND m."tenantId"=NEW."tenantId" AND m."userId"=NEW."actorUserId"
   AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner')
   AND q."toolName"='expenses.create' AND q.status='pending' AND q."encryptedArguments" IS NOT NULL
   AND q."expiresAt"=q."createdAt"+interval '10 minutes') THEN
  RAISE EXCEPTION 'R13 exact source principal and atomic existing approval required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R14_cash_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous "CashDeclaration"%ROWTYPE; class text;
BEGIN
 IF TG_OP='INSERT' THEN
  class=CASE WHEN NEW.revision=1 THEN 'declare_cash_position' ELSE 'correct_cash_position' END;
  IF NEW."countedAt">clock_timestamp() OR (NEW.revision>1 AND (NEW."encryptedReason" IS NULL OR length(NEW."encryptedReason")=0)) OR NOT EXISTS (
   SELECT 1 FROM "Membership" m JOIN "User" u ON u.id=m."userId" JOIN "ActionExecution" e ON e.id=NEW."actionExecutionId" AND e."tenantId"=NEW."tenantId"
   WHERE m.id=NEW."declaredByMembershipId" AND m."tenantId"=NEW."tenantId" AND m."userId"=NEW."declaredByUserId"
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','accountant')
    AND (m."branchId" IS NULL OR m."branchId"=NEW."branchId")
    AND e."actorUserId"=NEW."declaredByUserId" AND e."actionClass"=class AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW') THEN
   RAISE EXCEPTION 'R14 exact admitted declaration actor/observation required' USING ERRCODE='23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('r14/'||NEW."tenantId"||'/'||NEW."branchId"||'/'||NEW."businessDay",0));
  SELECT * INTO previous FROM "CashDeclaration" WHERE "tenantId"=NEW."tenantId" AND "branchId"=NEW."branchId" AND "businessDay"=NEW."businessDay" ORDER BY revision DESC LIMIT 1;
  IF (previous.id IS NULL AND (NEW.revision<>1 OR NEW."previousDeclarationId" IS NOT NULL)) OR
    (previous.id IS NOT NULL AND (NEW."previousDeclarationId" IS DISTINCT FROM previous.id OR NEW.revision<>previous.revision+1)) THEN
   RAISE EXCEPTION 'R14 stale exact branch/day predecessor' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD."encryptedReason" IS NOT NULL AND NEW."encryptedReason" IS NULL
  AND (to_jsonb(NEW)-'encryptedReason')=(to_jsonb(OLD)-'encryptedReason')
  AND "RC_payload_claim"(OLD."tenantId",'CashDeclaration',OLD.id,OLD."intentHash",OLD."createdAt"+interval '7 years','purge_cash_declaration_reason_payloads','package5.r14.cash-declaration-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY[OLD."actionExecutionId"])
 THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R14 immutable cash history / exact scoped reason claim required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."RC_confirmed_owner_receipt"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE item jsonb; ref text;
BEGIN
 item=to_jsonb(NEW); ref=item->>TG_ARGV[0];
 IF ref IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "ActionExecution" e
  WHERE e.id=ref AND e."tenantId"=item->>'tenantId' AND e.state='SUCCEEDED'
   AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
   AND e."reconciliationState" IN ('NOT_REQUIRED','RESOLVED')) THEN
  RAISE EXCEPTION 'R-C owner mutation requires the same committed canonical receipt' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.a18_guard_security_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE execution_ref TEXT;
BEGIN
  IF TG_TABLE_NAME='ClientConsentInvalidation' THEN
    PERFORM a18_assert_security_outcome(NEW."tenantId",NEW."actionExecutionId");
  ELSIF TG_TABLE_NAME='ActionExecution' THEN
    IF NEW."actionClass"='invalidate_client_consent_authority' AND NEW.state::text='SUCCEEDED' THEN
      PERFORM a18_assert_security_outcome(NEW."tenantId",NEW.id);
    END IF;
  ELSIF NEW."revocationEvidenceJson"->>'reason'='UNPROVEN_CLIENT_PROVENANCE' THEN
    SELECT i."actionExecutionId" INTO execution_ref FROM "ClientConsentInvalidation" i
      WHERE i."tenantId"=NEW."tenantId" AND i."invalidatedLinkId"=NEW.id LIMIT 1;
    PERFORM a18_assert_security_outcome(NEW."tenantId",execution_ref);
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.ai_confirmation_child_source_v1(child jsonb, tenant text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE operation TEXT := CASE child->>'actionClass'
  WHEN 'configure_crm_staff_access' THEN 'configure_staff_access'
  WHEN 'claim_crm_team_owner' THEN 'claim_team_owner'
  WHEN 'create_internal_provider_user' THEN 'create_provider_user'
  WHEN 'install_or_replace_crm_credentials' THEN 'install_crm_credentials'
  ELSE child->>'actionClass' END;
  material TEXT;
BEGIN
  IF child->>'family' = 'A28' THEN
    material := '{"operation":' || to_json(operation)::TEXT || ',"sourceIntentRef":' || to_json(child->>'sourceIntentRef')::TEXT || ',"tenantId":' || to_json(tenant)::TEXT || '}';
    RETURN 'p5w4:' || encode(sha256(convert_to(material,'UTF8')),'hex');
  END IF;
  material := '{"sourceIntentRef":' || to_json(child->>'sourceIntentRef')::TEXT || '}';
  RETURN CASE WHEN child->>'family'='A17' THEN 'p5w3:' ELSE 'p5w2:' END || encode(sha256(convert_to(material,'UTF8')),'hex');
END;
$function$

CREATE OR REPLACE FUNCTION public.appointment_account_membership_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Аккаунта нет — проверять нечего: это запись салона без клиента Maya.
  IF NEW."clientId" IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM "Membership" m
    WHERE m."userId" = NEW."clientId" AND m."tenantId" = NEW."tenantId"
  ) THEN
    RAISE EXCEPTION 'appointment_account_not_member_of_tenant'
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.b35_attempt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c "MarketingCampaign"%ROWTYPE; r "MarketingCampaignRecipient"%ROWTYPE;
 logical "MarketingCampaignRecipient"%ROWTYPE; previous "MarketingDeliveryAttempt"%ROWTYPE; seq INTEGER;
BEGIN
 SELECT * INTO c FROM "MarketingCampaign" WHERE id=COALESCE(NEW."campaignId",OLD."campaignId") AND "tenantId"=COALESCE(NEW."tenantId",OLD."tenantId");
 IF c."lifecycleVersion"=2 THEN RAISE EXCEPTION 'B35 coordinator cannot create provider attempts' USING ERRCODE='23514'; END IF;
 IF c."parentRecipientId" IS NULL THEN
  IF NEW."dispatchEligibilityJson" IS NOT NULL THEN RAISE EXCEPTION 'B35 dispatch proof requires bulk transport owner' USING ERRCODE='23514'; END IF;
  RETURN COALESCE(NEW,OLD);
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'B35 attempt history cannot be deleted' USING ERRCODE='23514'; END IF;
 SELECT * INTO r FROM "MarketingCampaignRecipient" WHERE id=NEW."recipientId" AND "tenantId"=NEW."tenantId" AND "campaignId"=c.id FOR UPDATE;
 SELECT * INTO logical FROM "MarketingCampaignRecipient" WHERE id=c."parentRecipientId" AND "tenantId"=c."tenantId";
 IF r."lifecycleVersion" IS DISTINCT FROM 1 OR NEW."lifecycleVersion"<>1 THEN RAISE EXCEPTION 'B35 transport recipient required' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT COALESCE(max("attemptNumber"),0)+1 INTO seq FROM "MarketingDeliveryAttempt" WHERE "tenantId"=NEW."tenantId" AND "recipientId"=r.id;
  IF NEW."attemptNumber"<>seq OR NEW.state<>'STARTED' OR r."terminalAt" IS NOT NULL
   OR r."leaseExpiresAt">=CURRENT_TIMESTAMP OR EXISTS (
    SELECT 1 FROM "MarketingDeliveryAttempt" WHERE "tenantId"=NEW."tenantId" AND "recipientId"=r.id AND state='STARTED'
   ) THEN RAISE EXCEPTION 'B35 attempt claim is not unique/openable' USING ERRCODE='23514'; END IF;
  IF NEW.kind='EXECUTION' AND (r."deliveryState"<>'NOT_SENT' OR r."externalDispatchState"<>'NOT_CROSSED'
   OR NEW."externalDispatchState"<>'NOT_CROSSED' OR NOT EXISTS (
    SELECT 1 FROM "ActionExecution" e WHERE e.id=c."actionExecutionId" AND e."tenantId"=c."tenantId" AND e.state='SUCCEEDED'
   ) OR EXISTS (
    SELECT 1 FROM "MarketingDeliveryAttempt" WHERE "tenantId"=NEW."tenantId" AND "recipientId"=r.id AND kind='EXECUTION'
      AND NOT (state='FAILED' AND "externalDispatchState"='NOT_CROSSED' AND "outcomeCode"='WORKER_LOST_BEFORE_DISPATCH')
   )) THEN RAISE EXCEPTION 'B35 effect requires successful admission; no repeat after outcome' USING ERRCODE='23514'; END IF;
  IF NEW.kind='EXECUTION' AND c."bulkSlotKey"<>'primary' AND NOT EXISTS (
   SELECT 1 FROM "MarketingCampaign" primary_envelope JOIN "MarketingCampaignRecipient" primary_leaf
    ON primary_leaf."campaignId"=primary_envelope.id AND primary_leaf."tenantId"=primary_envelope."tenantId"
   WHERE primary_envelope."parentRecipientId"=c."parentRecipientId" AND primary_envelope."tenantId"=c."tenantId"
    AND primary_envelope."bulkSlotKey"='primary' AND primary_leaf."deliveryState" IN ('ACCEPTED','DELIVERED')
  ) THEN RAISE EXCEPTION 'B35 supplemental effect requires actual primary acceptance' USING ERRCODE='23514'; END IF;
  IF NEW.kind='RECONCILIATION' AND (r."deliveryState"<>'UNKNOWN' OR r."reconciliationState"<>'REQUIRED'
    OR NEW."externalDispatchState"<>'NOT_APPLICABLE') THEN
   RAISE EXCEPTION 'B35 reconciliation requires original UNKNOWN' USING ERRCODE='23514'; END IF;
 ELSE
  IF OLD.state<>'STARTED' AND NEW."providerReferenceEncrypted" IS NULL AND OLD."providerReferenceEncrypted" IS NOT NULL
    AND OLD."payloadRetentionUntil" IS NOT NULL AND OLD."payloadRetentionUntil"<=CURRENT_TIMESTAMP
    AND (to_jsonb(NEW)-'providerReferenceEncrypted')=(to_jsonb(OLD)-'providerReferenceEncrypted') THEN
   RETURN NEW; -- Existing payload-retention authority may redact, never rewrite an outcome.
  END IF;
  IF OLD.state<>'STARTED' OR b35_pick(to_jsonb(OLD),ARRAY['id','tenantId','campaignId','recipientId','attemptNumber','kind','startedAt','createdAt','batchKey','lifecycleVersion','providerRequestIdentityHash','providerIdempotencyKeyHash','payloadRetentionUntil'])
   IS DISTINCT FROM b35_pick(to_jsonb(NEW),ARRAY['id','tenantId','campaignId','recipientId','attemptNumber','kind','startedAt','createdAt','batchKey','lifecycleVersion','providerRequestIdentityHash','providerIdempotencyKeyHash','payloadRetentionUntil']) THEN
   RAISE EXCEPTION 'B35 finished attempt / identity immutable' USING ERRCODE='23514'; END IF;
  IF OLD."externalDispatchState"<>'NOT_CROSSED' AND NEW."dispatchEligibilityJson" IS DISTINCT FROM OLD."dispatchEligibilityJson" THEN
   RAISE EXCEPTION 'B35 dispatch eligibility is sealed' USING ERRCODE='23514'; END IF;
  IF OLD."externalDispatchState"='MAY_HAVE_CROSSED' AND NEW."externalDispatchState" NOT IN ('MAY_HAVE_CROSSED','ACKNOWLEDGED') THEN
   RAISE EXCEPTION 'B35 provider boundary cannot be erased' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.kind='EXECUTION' AND NEW."externalDispatchState"<>'NOT_CROSSED' THEN
  IF NOT COALESCE(NEW."dispatchEligibilityJson" @> jsonb_build_object('contract','maya.bulk-dispatch-eligibility/1',
   'tenantId',NEW."tenantId",'clientId',logical."clientId",'decision','ALLOW'),false)
   OR NULLIF(NEW."dispatchEligibilityJson"->>'checkedAt','') IS NULL THEN
   RAISE EXCEPTION 'B35 dispatch boundary requires current ALLOW evidence' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.b35_audience_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a "MarketingAudience"%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME = 'MarketingAudience' THEN
  IF TG_OP <> 'INSERT' AND OLD."snapshotContract" IS NOT NULL THEN
   IF TG_OP = 'DELETE' OR (OLD.status = 'FROZEN' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD)) THEN
    RAISE EXCEPTION 'B35 immutable audience' USING ERRCODE = '23514';
   END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW."snapshotContract" IS DISTINCT FROM OLD."snapshotContract" THEN
   RAISE EXCEPTION 'B35 historical audience promotion forbidden' USING ERRCODE = '23514';
  END IF;
 ELSE
  SELECT * INTO a FROM "MarketingAudience" WHERE id = COALESCE(NEW."audienceId",OLD."audienceId")
   AND "tenantId" = COALESCE(NEW."tenantId",OLD."tenantId") FOR UPDATE;
  IF TG_OP = 'UPDATE' AND (NEW."audienceId",NEW."tenantId",NEW."clientId") IS DISTINCT FROM (OLD."audienceId",OLD."tenantId",OLD."clientId") THEN
   IF OLD."clientId" IS NOT NULL OR NEW."clientId" IS NOT NULL THEN
    RAISE EXCEPTION 'B35 audience member identity immutable' USING ERRCODE = '23514';
   END IF;
  END IF;
  IF a."snapshotContract" IS NOT NULL THEN
   IF a.status = 'FROZEN' OR TG_OP = 'DELETE' OR NEW."clientId" IS NULL OR NEW."internalUserId" IS NOT NULL THEN
    RAISE EXCEPTION 'B35 frozen audience / canonical Client required' USING ERRCODE = '23514';
   END IF;
  ELSIF NEW."clientId" IS NOT NULL THEN
   RAISE EXCEPTION 'B35 Client requires canonical audience' USING ERRCODE = '23514';
  END IF;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.b35_audience_sealed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a "MarketingAudience"%ROWTYPE; n INTEGER;
BEGIN
 SELECT * INTO a FROM "MarketingAudience" WHERE id=NEW.id;
 IF a."snapshotContract" IS NULL THEN RETURN NULL; END IF;
 SELECT count(*) INTO n FROM "MarketingAudienceRecipient" WHERE "tenantId"=a."tenantId" AND "audienceId"=a.id;
 IF a.status <> 'FROZEN' OR n <> a."eligibleCount" OR EXISTS (
  SELECT 1 FROM "MarketingAudienceRecipient" WHERE "tenantId"=a."tenantId" AND "audienceId"=a.id AND "clientId" IS NULL
 ) THEN RAISE EXCEPTION 'B35 audience must commit sealed with exact canonical members' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.b35_graph_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c "MarketingCampaign"%ROWTYPE; r "MarketingCampaignRecipient"%ROWTYPE;
 a "MarketingAudience"%ROWTYPE; e "ActionExecution"%ROWTYPE; n INTEGER; m INTEGER;
 campaign_id TEXT; tid TEXT; route JSONB; slotrow RECORD; leaf RECORD;
BEGIN
 tid:=NEW."tenantId";
 IF TG_TABLE_NAME='MarketingCampaign' THEN campaign_id:=NEW.id;
 ELSIF TG_TABLE_NAME='MarketingCampaignRecipient' THEN campaign_id:=NEW."campaignId";
 ELSE
  SELECT mc.id INTO campaign_id FROM "MarketingCampaign" mc WHERE mc."actionExecutionId"=NEW.id AND mc."tenantId"=tid;
  IF campaign_id IS NULL AND NEW.capability IN ('communication.bulk-campaign.admit.v2','communication.bulk-slot.admit.v2')
   AND NEW.state NOT IN ('PENDING_APPROVAL','NOT_EXECUTED') THEN
   RAISE EXCEPTION 'B35 admission requires exact durable graph' USING ERRCODE='23514';
  END IF;
 END IF;
 SELECT * INTO c FROM "MarketingCampaign" WHERE "MarketingCampaign".id=campaign_id AND "tenantId"=tid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF c."lifecycleVersion"=2 THEN
  SELECT * INTO a FROM "MarketingAudience" WHERE "MarketingAudience".id=c."audienceId" AND "tenantId"=tid;
  IF a."snapshotContract" IS DISTINCT FROM 'maya.bulk-client-audience/1' OR a.status IS DISTINCT FROM 'FROZEN'
    OR a."snapshotHash" IS DISTINCT FROM c."audienceSnapshotHash" OR a."eligibleCount"<>c."recipientCount" THEN
   RAISE EXCEPTION 'B35 exact sealed audience required' USING ERRCODE='23514';
  END IF;
  IF c."confirmedAt" IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO e FROM "ActionExecution" WHERE "ActionExecution".id=c."actionExecutionId" AND "tenantId"=tid;
  IF e.capability IS DISTINCT FROM 'communication.bulk-campaign.admit.v2' OR e."actionClass" IS DISTINCT FROM 'deliver_bulk_campaign'
   OR e."targetRef" IS DISTINCT FROM c.id OR e."approvalDecision" IS DISTINCT FROM 'APPROVED'
   OR e."approvalDecidedByUserId" IS DISTINCT FROM c."confirmedByUserId" OR e."approvalDecidedAt" IS DISTINCT FROM c."confirmedAt"
   OR NOT COALESCE(e."evidenceRefsJson" @> jsonb_build_array('b35:intent:'||c."bulkIntentHash"),false) THEN
   RAISE EXCEPTION 'B35 matching immutable Action Engine approval required' USING ERRCODE='23514';
  END IF;
  IF EXISTS (
   (SELECT "clientId" FROM "MarketingAudienceRecipient" WHERE "tenantId"=tid AND "audienceId"=c."audienceId"
    EXCEPT SELECT "clientId" FROM "MarketingCampaignRecipient" WHERE "tenantId"=tid AND "campaignId"=c.id AND "lifecycleVersion"=2)
   UNION ALL
   (SELECT "clientId" FROM "MarketingCampaignRecipient" WHERE "tenantId"=tid AND "campaignId"=c.id
    EXCEPT SELECT "clientId" FROM "MarketingAudienceRecipient" WHERE "tenantId"=tid AND "audienceId"=c."audienceId")
  ) THEN RAISE EXCEPTION 'B35 approved audience/Client child set must be equal' USING ERRCODE='23514'; END IF;
  -- Verify references only at first seal, not on later revocation/reconciliation.
  IF TG_TABLE_NAME='MarketingCampaign' AND (TG_OP='INSERT' OR to_jsonb(OLD)->>'confirmedAt' IS NULL) THEN
   FOR r IN SELECT * FROM "MarketingCampaignRecipient" WHERE "tenantId"=tid AND "campaignId"=c.id LOOP
    route:=r."routePlanJson";
    IF route->>'link' IS NOT NULL AND NOT EXISTS (
     SELECT 1 FROM "ClientChannelLink" l WHERE l.id=route->'link'->>'id' AND l."tenantId"=tid AND l."clientId"=r."clientId"
      AND l.provider=route->'link'->>'provider' AND l."providerSubjectHash"=route->'link'->>'subjectHash'
      AND l."verificationEvidenceHash"=route->'link'->>'verificationEvidenceHash' AND l."revokedAt" IS NULL
      AND l.provider=CASE route->>'primary' WHEN 'inbox' THEN 'maya_user' ELSE 'telegram' END
    ) THEN RAISE EXCEPTION 'B35 route binding foreign/revoked/mismatched' USING ERRCODE='23514'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(route->'webPushEndpoints') ep WHERE NOT EXISTS (
     SELECT 1 FROM "ClientWebPushEndpoint" p WHERE p.id=ep->>'id' AND p."tenantId"=tid AND p."clientId"=r."clientId"
      AND p."clientChannelLinkId"=ep->>'clientChannelLinkId' AND p."materialHash"=ep->>'materialHash' AND p."endedAt" IS NULL
    )) THEN RAISE EXCEPTION 'B35 Web Push plan foreign/ended/mismatched' USING ERRCODE='23514'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(route->'apnsDevices') d WHERE NOT EXISTS (
     SELECT 1 FROM "DevicePushToken" p WHERE p.id=d->>'id' AND p."tenantId"=tid AND p."userId"=route->>'userId'
    )) THEN RAISE EXCEPTION 'B35 APNs plan foreign/missing' USING ERRCODE='23514'; END IF;
   END LOOP;
  END IF;
  IF c."aggregateState" IN ('COMPLETED','PARTIAL','FAILED','SKIPPED','CANCELLED','EXPIRED') AND EXISTS (
   SELECT 1 FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id
    AND (cr."terminalAt" IS NULL OR cr."aggregateState" IN ('READY','RUNNING','UNRESOLVED'))
  ) THEN RAISE EXCEPTION 'B35 root cannot terminalize pending/UNKNOWN children' USING ERRCODE='23514'; END IF;
  IF c."aggregateState" IN ('COMPLETED','PARTIAL','FAILED','SKIPPED','CANCELLED','EXPIRED') AND c."aggregateState"::text IS DISTINCT FROM (
   SELECT CASE WHEN count(*)=0 THEN 'SKIPPED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='COMPLETED')=count(*) THEN 'COMPLETED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='FAILED')=count(*) THEN 'FAILED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='CANCELLED')=count(*) THEN 'CANCELLED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='EXPIRED')=count(*) THEN 'EXPIRED'
    WHEN count(*) FILTER (WHERE cr."aggregateState" IN ('SKIPPED','CANCELLED','EXPIRED'))=count(*) THEN 'SKIPPED'
    ELSE 'PARTIAL' END
   FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id
  ) THEN RAISE EXCEPTION 'B35 root outcome must project actual Client outcomes' USING ERRCODE='23514'; END IF;
 ELSIF c."parentRecipientId" IS NOT NULL THEN
  SELECT * INTO r FROM "MarketingCampaignRecipient" WHERE "MarketingCampaignRecipient".id=c."parentRecipientId" AND "tenantId"=tid;
  IF r."lifecycleVersion" IS DISTINCT FROM 2 OR NOT EXISTS (
   SELECT 1 FROM "MarketingCampaign" p WHERE p.id=r."campaignId" AND p."tenantId"=tid AND p."lifecycleVersion"=2 AND p."confirmedAt" IS NOT NULL
  ) OR NOT EXISTS (SELECT 1 FROM b35_slots(r."routePlanJson") s WHERE s.slot=c."bulkSlotKey" AND s.channel=c.channel) THEN
   RAISE EXCEPTION 'B35 transport must fill an originally approved slot' USING ERRCODE='23514';
  END IF;
  SELECT * INTO e FROM "ActionExecution" WHERE "ActionExecution".id=c."actionExecutionId" AND "tenantId"=tid;
  IF e.capability IS DISTINCT FROM 'communication.bulk-slot.admit.v2' OR e."actionClass" IS DISTINCT FROM 'deliver_bulk_campaign'
    OR e."targetRef" IS DISTINCT FROM r.id OR NOT COALESCE(e."evidenceRefsJson" @> jsonb_build_array('b35:slot:'||c."bulkSlotKey"),false) THEN
   RAISE EXCEPTION 'B35 transport admission binding mismatch' USING ERRCODE='23514';
  END IF;
  SELECT count(*) INTO n FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id;
  IF n<>c."recipientCount" THEN RAISE EXCEPTION 'B35 transport leaf set must match exact pinned count' USING ERRCODE='23514'; END IF;
  FOR leaf IN SELECT * FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id LOOP
   IF (CASE c.channel
    WHEN 'inbox' THEN leaf."recipientKind"='internal_user' AND leaf."internalUserId"=r."routePlanJson"->>'userId'
      AND leaf."eligibilityEvidenceRef"='b35:link:'||(r."routePlanJson"->'link'->>'id')
    WHEN 'telegram' THEN leaf."recipientKind"='telegram_chat' AND leaf."internalUserId" IS NULL
      AND leaf."eligibilityEvidenceRef"='b35:link:'||(r."routePlanJson"->'link'->>'id')
    WHEN 'apns' THEN leaf."recipientKind"='device_token' AND leaf."internalUserId"=r."routePlanJson"->>'userId'
      AND leaf."eligibilityEvidenceRef"='b35:device:'||substring(c."bulkSlotKey" FROM 6)
    WHEN 'web_push' THEN leaf."recipientKind"='client_web_push_endpoint' AND leaf."internalUserId" IS NULL AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(r."routePlanJson"->'webPushEndpoints') ep
       WHERE leaf."eligibilityEvidenceRef"='b35:endpoint:'||(ep->>'id'))
    ELSE false END) IS NOT TRUE THEN
    RAISE EXCEPTION 'B35 leaf must retain exact planned endpoint reference' USING ERRCODE='23514';
   END IF;
  END LOOP;
  IF (SELECT count(DISTINCT cr."eligibilityEvidenceRef") FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id) <> c."recipientCount" THEN
   RAISE EXCEPTION 'B35 duplicate endpoint leaf forbidden' USING ERRCODE='23514'; END IF;
  IF c.channel='web_push' THEN
   IF c."recipientCount" <> jsonb_array_length(r."routePlanJson"->'webPushEndpoints') THEN
    RAISE EXCEPTION 'B35 exact pinned Web Push fanout required' USING ERRCODE='23514'; END IF;
  ELSIF c."recipientCount"<>1 THEN RAISE EXCEPTION 'B35 single fixed transport recipient required' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.b35_graph_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE root "MarketingCampaign"%ROWTYPE; parent "MarketingCampaignRecipient"%ROWTYPE;
 oldj JSONB; newj JSONB; keys TEXT[]; sealed BOOLEAN; owned BOOLEAN;
BEGIN
 oldj:=to_jsonb(OLD); newj:=to_jsonb(NEW);
 IF TG_TABLE_NAME='MarketingCampaign' THEN
  owned:=COALESCE(NEW."lifecycleVersion"=2 OR NEW."parentRecipientId" IS NOT NULL,false)
   OR COALESCE(OLD."lifecycleVersion"=2 OR OLD."parentRecipientId" IS NOT NULL,false);
  IF NOT owned THEN RETURN COALESCE(NEW,OLD); END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'B35 durable identity cannot be deleted' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (NEW.id,NEW."tenantId",NEW."lifecycleVersion",NEW."parentRecipientId",NEW."bulkSlotKey")
    IS DISTINCT FROM (OLD.id,OLD."tenantId",OLD."lifecycleVersion",OLD."parentRecipientId",OLD."bulkSlotKey") THEN
   RAISE EXCEPTION 'B35 role/identity immutable; no historical promotion' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND OLD."aggregateState" IN ('COMPLETED','PARTIAL','FAILED','SKIPPED','CANCELLED','EXPIRED')
   AND NEW."aggregateState" IS DISTINCT FROM OLD."aggregateState" THEN
   RAISE EXCEPTION 'B35 terminal campaign cannot reopen' USING ERRCODE='23514';
  END IF;
  sealed:=TG_OP='UPDATE' AND (OLD."confirmedAt" IS NOT NULL OR OLD."parentRecipientId" IS NOT NULL);
  keys:=ARRAY['id','tenantId','lifecycleVersion','parentRecipientId','bulkSlotKey','bulkIntentContract','bulkIntentHash',
   'createdByUserId','audienceId','channel','provider','message','recipientUserIdsJson','recipientCount','idempotencyKey',
   'expiresAt','createdAt','audienceSnapshotHash','messageSnapshotHash','confirmationHash','confirmedAt','confirmedByUserId',
   'scheduledFor','scope','actionExecutionId','contentRef','deliveryCapabilityKey','deliveryCapabilityVersion',
   'retryPolicyKey','retryPolicyVersion','reconciliationPolicyKey','reconciliationPolicyVersion','payloadRetentionUntil','auditRetentionUntil'];
 ELSE
  SELECT * INTO root FROM "MarketingCampaign" WHERE id=COALESCE(NEW."campaignId",OLD."campaignId")
   AND "tenantId"=COALESCE(NEW."tenantId",OLD."tenantId") FOR UPDATE;
  owned:=root."lifecycleVersion"=2 OR root."parentRecipientId" IS NOT NULL
    OR COALESCE(OLD."lifecycleVersion"=2,false) OR COALESCE(NEW."lifecycleVersion"=2,false);
  IF NOT owned THEN RETURN COALESCE(NEW,OLD); END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'B35 durable recipient cannot be deleted' USING ERRCODE='23514'; END IF;
  IF (root."lifecycleVersion"=2) IS DISTINCT FROM (NEW."lifecycleVersion"=2) THEN
   RAISE EXCEPTION 'B35 logical/transport role mismatch' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND root."lifecycleVersion"=2 AND root."confirmedAt" IS NOT NULL THEN
   RAISE EXCEPTION 'B35 confirmed member set immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NEW."contentEncrypted" IS NULL AND NEW."lifecycleVersion"=2 THEN
   RAISE EXCEPTION 'B35 new Client content must be durable' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND (NEW.id,NEW."tenantId",NEW."campaignId",NEW."lifecycleVersion",NEW."clientId")
   IS DISTINCT FROM (OLD.id,OLD."tenantId",OLD."campaignId",OLD."lifecycleVersion",OLD."clientId") THEN
   RAISE EXCEPTION 'B35 recipient identity immutable' USING ERRCODE='23514';
  END IF;
  sealed:=TG_OP='UPDATE' AND (root."confirmedAt" IS NOT NULL OR root."parentRecipientId" IS NOT NULL);
  keys:=ARRAY['id','tenantId','campaignId','clientId','lifecycleVersion','externalClientId','internalUserId','idempotencyKey',
   'createdAt','identityVersion','recipientKind','recipientRefHash','contentIdentityHash','routePlanJson',
   'payloadRetentionUntil','auditRetentionUntil','consentEvidenceId','eligibilityEvidenceRef'];
  IF sealed AND NEW."contentEncrypted" IS DISTINCT FROM OLD."contentEncrypted" AND NOT (
   NEW."contentEncrypted" IS NULL AND OLD."terminalAt" IS NOT NULL
   AND OLD."payloadRetentionUntil" IS NOT NULL AND OLD."payloadRetentionUntil" <= CURRENT_TIMESTAMP
  ) THEN RAISE EXCEPTION 'B35 immutable Client content' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND OLD."leaseTokenHash" IS NOT NULL AND NEW."leaseTokenHash" IS NOT NULL
   AND NEW."leaseTokenHash" IS DISTINCT FROM OLD."leaseTokenHash" AND OLD."leaseExpiresAt">CURRENT_TIMESTAMP THEN
   RAISE EXCEPTION 'B35 live lease cannot be stolen' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND NEW.revision <= OLD.revision THEN
   RAISE EXCEPTION 'B35 recipient revision must advance' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND OLD."terminalAt" IS NOT NULL AND
   (to_jsonb(NEW)-ARRAY['updatedAt','revision','contentEncrypted']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['updatedAt','revision','contentEncrypted'])
  THEN RAISE EXCEPTION 'B35 terminal outcome cannot reopen or change' USING ERRCODE='23514'; END IF;
 END IF;
 IF sealed AND b35_pick(oldj,keys) IS DISTINCT FROM b35_pick(newj,keys) THEN
  RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: B35 approved intent is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.b35_history_epoch_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."canonicalHistoryStartedAt" IS NOT NULL THEN RAISE EXCEPTION 'B35 history epoch cannot be erased' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND OLD."canonicalHistoryStartedAt" IS NOT NULL THEN
  IF NEW."tenantId" IS DISTINCT FROM OLD."tenantId" OR NEW."canonicalHistoryStartedAt" IS DISTINCT FROM OLD."canonicalHistoryStartedAt" THEN
   RAISE EXCEPTION 'B35 history epoch is write-once' USING ERRCODE='23514'; END IF;
 ELSIF NEW."canonicalHistoryStartedAt" IS NOT NULL THEN
  NEW."canonicalHistoryStartedAt":=timezone('UTC',CURRENT_TIMESTAMP)::timestamp(3);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.b35_outcome_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r "MarketingCampaignRecipient"%ROWTYPE; c "MarketingCampaign"%ROWTYPE;
 a "MarketingDeliveryAttempt"%ROWTYPE; n INTEGER; missing INTEGER; pending INTEGER; unknowns INTEGER;
 successes INTEGER; failures INTEGER; skips INTEGER; projected TEXT;
BEGIN
 SELECT * INTO r FROM "MarketingCampaignRecipient" WHERE id=NEW.id;
 SELECT * INTO c FROM "MarketingCampaign" WHERE id=r."campaignId" AND "tenantId"=r."tenantId";
 IF r."lifecycleVersion"=2 THEN
  IF r."terminalAt" IS NULL THEN RETURN NULL; END IF;
  SELECT count(*) INTO missing FROM b35_slots(r."routePlanJson") s WHERE NOT EXISTS (
   SELECT 1 FROM "MarketingCampaign" e WHERE e."tenantId"=r."tenantId" AND e."parentRecipientId"=r.id AND e."bulkSlotKey"=s.slot
  );
  SELECT count(*) FILTER (WHERE leaf."deliveryState"='NOT_SENT'), count(*) FILTER (WHERE leaf."deliveryState"='UNKNOWN'),
   count(*) FILTER (WHERE leaf."deliveryState" IN ('ACCEPTED','DELIVERED')),
   count(*) FILTER (WHERE leaf."deliveryState"='FAILED'), count(*) FILTER (WHERE leaf."deliveryState"='SKIPPED')
  INTO pending,unknowns,successes,failures,skips
  FROM "MarketingCampaign" e JOIN "MarketingCampaignRecipient" leaf ON leaf."campaignId"=e.id AND leaf."tenantId"=e."tenantId"
  WHERE e."tenantId"=r."tenantId" AND e."parentRecipientId"=r.id;
  IF missing>0 OR pending>0 OR unknowns>0 THEN RAISE EXCEPTION 'B35 partial/UNKNOWN cannot become terminal' USING ERRCODE='23514'; END IF;
  projected:=CASE WHEN successes>0 AND failures+skips=0 THEN 'COMPLETED'
   WHEN successes>0 THEN 'PARTIAL' WHEN failures>0 AND skips=0 THEN 'FAILED'
   WHEN failures>0 THEN 'PARTIAL' ELSE 'SKIPPED' END;
  IF r."aggregateState"::text<>projected AND NOT (projected='SKIPPED' AND r."aggregateState" IN ('EXPIRED','CANCELLED')) THEN
   RAISE EXCEPTION 'B35 aggregate must match actual leaves' USING ERRCODE='23514'; END IF;
 ELSIF c."parentRecipientId" IS NOT NULL THEN
  SELECT * INTO a FROM "MarketingDeliveryAttempt" WHERE "recipientId"=r.id AND "tenantId"=r."tenantId" ORDER BY "attemptNumber" DESC LIMIT 1;
  SELECT count(*) INTO n FROM "MarketingDeliveryAttempt" WHERE "recipientId"=r.id AND "tenantId"=r."tenantId";
  IF r."attemptCount"<>n OR ((a.state='STARTED') IS DISTINCT FROM (r."leaseOwner" IS NOT NULL) AND n>0) THEN
   RAISE EXCEPTION 'B35 lease/count must match owned attempt' USING ERRCODE='23514'; END IF;
  IF r."deliveryState" IN ('ACCEPTED','DELIVERED') AND NOT COALESCE(a.state='SUCCEEDED' AND (a."externalDispatchState"='ACKNOWLEDGED' OR a.kind='RECONCILIATION'),false) THEN
   RAISE EXCEPTION 'B35 confirmed delivery requires owned successful attempt' USING ERRCODE='23514'; END IF;
  IF r."deliveryState"='UNKNOWN' AND NOT COALESCE((a.state='UNKNOWN' OR a.kind='RECONCILIATION') AND r."externalDispatchState"='MAY_HAVE_CROSSED',false) THEN
   RAISE EXCEPTION 'B35 UNKNOWN evidence must survive' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND OLD."deliveryState"='UNKNOWN' AND r."deliveryState"<>'UNKNOWN' AND NOT COALESCE(a.kind='RECONCILIATION' AND a.state='SUCCEEDED' AND r."reconciliationState"='RESOLVED',false) THEN
   RAISE EXCEPTION 'B35 UNKNOWN requires proven reconciliation' USING ERRCODE='23514'; END IF;
  IF r."externalDispatchState"='MAY_HAVE_CROSSED' AND NOT COALESCE(a."externalDispatchState"='MAY_HAVE_CROSSED' OR a.kind='RECONCILIATION',false) THEN
   RAISE EXCEPTION 'B35 boundary must match attempt' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.b35_route_shape(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE e JSONB; keys TEXT[];
BEGIN
 IF p IS NULL OR jsonb_typeof(p) <> 'object' THEN RETURN false; END IF;
 SELECT array_agg(k ORDER BY k) INTO keys FROM jsonb_object_keys(p) k;
 IF keys <> ARRAY['apnsDevices','contract','link','policyVersion','primary','userId','webPushEndpoints']
 OR p->>'contract' IS DISTINCT FROM 'maya.bulk-client-route/1'
 OR p->>'primary' NOT IN ('inbox','telegram','web_push','none')
 OR p->>'policyVersion' IS DISTINCT FROM '1'
 OR jsonb_typeof(p->'webPushEndpoints') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p->'apnsDevices') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF jsonb_array_length(p->'webPushEndpoints') > 5 THEN RETURN false; END IF;
 IF (p->>'primary' = 'inbox') IS DISTINCT FROM (p->>'userId' IS NOT NULL)
 OR (p->>'primary' IN ('inbox','telegram')) IS DISTINCT FROM (p->>'link' IS NOT NULL)
 OR (p->>'primary' <> 'inbox' AND jsonb_array_length(p->'apnsDevices') > 0)
 OR (p->>'primary' = 'none' AND jsonb_array_length(p->'webPushEndpoints') > 0)
 OR (p->>'primary' = 'web_push' AND jsonb_array_length(p->'webPushEndpoints') = 0) THEN RETURN false; END IF;
 IF p->>'link' IS NOT NULL THEN
  e := p->'link';
  SELECT array_agg(k ORDER BY k) INTO keys FROM jsonb_object_keys(e) k;
  IF keys <> ARRAY['id','provider','subjectHash','verificationEvidenceHash']
  OR NULLIF(e->>'id','') IS NULL OR NULLIF(e->>'provider','') IS NULL
  OR NOT COALESCE(e->>'subjectHash' ~ '^[a-f0-9]{64}$',false)
  OR NOT COALESCE(e->>'verificationEvidenceHash' ~ '^[a-f0-9]{64}$',false) THEN RETURN false; END IF;
 END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p->'webPushEndpoints') LOOP
  SELECT array_agg(k ORDER BY k) INTO keys FROM jsonb_object_keys(e) k;
  IF keys <> ARRAY['clientChannelLinkId','id','materialHash'] OR NULLIF(e->>'id','') IS NULL
  OR NULLIF(e->>'clientChannelLinkId','') IS NULL OR NOT COALESCE(e->>'materialHash' ~ '^[a-f0-9]{64}$',false) THEN RETURN false; END IF;
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(p->'apnsDevices') LOOP
  SELECT array_agg(k ORDER BY k) INTO keys FROM jsonb_object_keys(e) k;
  IF keys <> ARRAY['id','tokenHash'] OR NULLIF(e->>'id','') IS NULL
  OR NOT COALESCE(e->>'tokenHash' ~ '^[a-f0-9]{64}$',false) THEN RETURN false; END IF;
 END LOOP;
 RETURN (SELECT count(*)=count(DISTINCT value->>'id') FROM jsonb_array_elements(p->'webPushEndpoints'))
 AND (SELECT count(*)=count(DISTINCT value->>'id') FROM jsonb_array_elements(p->'apnsDevices'));
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.check_agent_task_cross_row_invariants()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  opportunity_record RECORD;
BEGIN
  SELECT opportunity."status", opportunity."expiresAt",
         opportunity."outcome", opportunity."recommendedAgentDomain"
    INTO opportunity_record
  FROM "Opportunity" opportunity
  WHERE opportunity."id" = NEW."opportunityId"
    AND opportunity."tenantId" = NEW."tenantId"
    AND opportunity."semanticKey" = NEW."semanticKey";

  IF NEW."expiresAt" > opportunity_record."expiresAt" THEN
    RAISE EXCEPTION 'AgentTask cannot outlive its Opportunity'
      USING ERRCODE = '23514';
  END IF;

  IF NEW."status" = 'current' AND opportunity_record."status" <> 'active' THEN
    RAISE EXCEPTION 'Current AgentTask requires active Opportunity'
      USING ERRCODE = '23514';
  END IF;

  IF NEW."status" = 'current' AND opportunity_record."outcome" = 'inform_only' THEN
    RAISE EXCEPTION 'Inform-only Opportunity cannot create AgentTask'
      USING ERRCODE = '23514';
  END IF;

  IF NEW."agentDomain" <> opportunity_record."recommendedAgentDomain" THEN
    RAISE EXCEPTION 'AgentTask domain must match Opportunity route'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_ai_confirmation_children_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE child JSONB; matches INTEGER;
BEGIN
  IF NEW."confirmationReceiptJson" IS NULL OR NEW."status" <> 'confirmed' THEN RETURN NULL; END IF;
  FOR child IN SELECT value FROM jsonb_array_elements(NEW."confirmationReceiptJson"->'children') LOOP
    SELECT count(*) INTO matches FROM "ActionExecution" e WHERE e."tenantId"=NEW."confirmedTenantId"
      AND e."sourceRef"=ai_confirmation_child_source_v1(child,NEW."confirmedTenantId")
      AND e."actionClass"=child->>'actionClass' AND e."targetKind"=child->>'targetKind'
      AND (child->'targetRef'='null'::JSONB OR e."targetRef"=child->>'targetRef')
      AND e."actorUserId"=NEW."confirmationReceiptJson"->>'ownerUserId'
      AND e."capability" LIKE 'package5.%.execute.v1' AND e."state"='SUCCEEDED'
      AND EXISTS (SELECT 1 FROM "ActionTargetMutation" m WHERE m."tenantId"=e."tenantId" AND m."actionExecutionId"=e."id");
    IF matches <> 1 THEN RAISE EXCEPTION 'Confirmation requires every exact canonical child outcome' USING ERRCODE='23514'; END IF;
  END LOOP;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_opportunity_cross_row_invariants()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  successor_count INTEGER;
  predecessor_record RECORD;
  current_task_count INTEGER;
BEGIN
  IF NEW."status" = 'superseded' THEN
    SELECT COUNT(*) INTO successor_count
    FROM "Opportunity" successor
    WHERE successor."tenantId" = NEW."tenantId"
      AND successor."semanticKey" = NEW."semanticKey"
      AND successor."supersedesOpportunityId" = NEW."id"
      AND successor."revision" = NEW."revision" + 1;

    IF successor_count <> 1 THEN
      RAISE EXCEPTION 'Superseded Opportunity requires exactly one next revision'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW."status" <> 'active' THEN
    SELECT COUNT(*) INTO current_task_count
    FROM "AgentTask" task
    WHERE task."tenantId" = NEW."tenantId"
      AND task."opportunityId" = NEW."id"
      AND task."status" = 'current';

    IF current_task_count <> 0 THEN
      RAISE EXCEPTION 'Terminal Opportunity cannot retain a current AgentTask'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW."supersedesOpportunityId" IS NOT NULL THEN
    SELECT predecessor."tenantId", predecessor."semanticKey",
           predecessor."revision", predecessor."status"
      INTO predecessor_record
    FROM "Opportunity" predecessor
    WHERE predecessor."id" = NEW."supersedesOpportunityId";

    IF predecessor_record."tenantId" IS DISTINCT FROM NEW."tenantId"
      OR predecessor_record."semanticKey" IS DISTINCT FROM NEW."semanticKey"
      OR predecessor_record."revision" + 1 <> NEW."revision"
      OR predecessor_record."status" <> 'superseded'
    THEN
      RAISE EXCEPTION 'Invalid Opportunity supersession chain'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_active_loyalty_redemption_grant_revocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  grant_issued_at TIMESTAMP(3);
  grant_expires_at TIMESTAMP(3);
BEGIN
  SELECT "issuedAt", "expiresAt"
  INTO grant_issued_at, grant_expires_at
  FROM "LoyaltyRedemptionGrant"
  WHERE "id" = NEW."grantId"
    AND "tenantId" = NEW."tenantId"
  FOR UPDATE;

  -- Let the tenant-qualified FK produce the canonical missing/cross-tenant
  -- rejection when the grant is not visible in this tenant.
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF CURRENT_TIMESTAMP >= grant_expires_at
    OR NEW."revokedAt" < grant_issued_at
    OR NEW."revokedAt" >= grant_expires_at
  THEN
    RAISE EXCEPTION 'LoyaltyRedemptionGrantRevocation requires an active grant'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM "LoyaltyRedemption"
    WHERE "grantId" = NEW."grantId"
      AND "tenantId" = NEW."tenantId"
  )
  THEN
    RAISE EXCEPTION 'Consumed LoyaltyRedemptionGrant cannot be revoked'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_customer_subscription_usage_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  allowed_units INTEGER;
  already_used_units INTEGER;
  allowed_from TIMESTAMP(3);
  allowed_until TIMESTAMP(3);
BEGIN
  SELECT "visitsIncluded", "termStartsAt", "termEndsAt"
  INTO allowed_units, allowed_from, allowed_until
  FROM "CustomerSubscription"
  WHERE "id" = NEW."subscriptionId"
    AND "tenantId" = NEW."tenantId"
  FOR UPDATE;

  -- Let the composite FK reject a missing or cross-tenant subscription.
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF NEW."usedAt" < allowed_from OR NEW."usedAt" > allowed_until THEN
    RAISE EXCEPTION 'CustomerSubscriptionUsage falls outside the immutable term'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(SUM("units"), 0)
  INTO already_used_units
  FROM "CustomerSubscriptionUsage"
  WHERE "subscriptionId" = NEW."subscriptionId"
    AND "tenantId" = NEW."tenantId";

  IF already_used_units + NEW."units" > allowed_units THEN
    RAISE EXCEPTION 'CustomerSubscription usage exceeds the immutable term allowance'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_non_revoked_loyalty_redemption()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  grant_issued_at TIMESTAMP(3);
  grant_expires_at TIMESTAMP(3);
BEGIN
  SELECT "issuedAt", "expiresAt"
  INTO grant_issued_at, grant_expires_at
  FROM "LoyaltyRedemptionGrant"
  WHERE "id" = NEW."grantId"
    AND "tenantId" = NEW."tenantId"
  FOR UPDATE;

  -- Let the tenant-qualified FK produce the canonical missing/cross-tenant
  -- rejection when the grant is not visible in this tenant.
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF NEW."redeemedAt" < grant_issued_at
    OR NEW."redeemedAt" >= grant_expires_at
    OR (
      NEW."actionExecutionId" IS NOT NULL
      AND CURRENT_TIMESTAMP >= grant_expires_at
    )
  THEN
    RAISE EXCEPTION 'LoyaltyRedemption requires an unexpired grant'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM "LoyaltyRedemptionGrantRevocation"
    WHERE "grantId" = NEW."grantId"
      AND "tenantId" = NEW."tenantId"
  )
  THEN
    RAISE EXCEPTION 'Revoked LoyaltyRedemptionGrant cannot be consumed'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_one_time_gift_certificate_redemption()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  certificate_status TEXT;
  certificate_paid_at TIMESTAMP(3);
  certificate_expires_at TIMESTAMP(3);
BEGIN
  SELECT "paymentStatus", "paidAt", "expiresAt"
  INTO certificate_status, certificate_paid_at, certificate_expires_at
  FROM "GiftCertificate"
  WHERE "id" = NEW."certificateId"
    AND "tenantId" = NEW."tenantId"
  FOR UPDATE;

  -- Let the tenant-qualified FK produce the canonical missing/cross-tenant
  -- rejection when the certificate is not visible in this tenant.
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF certificate_status <> 'paid'
    OR NEW."redeemedAt" < certificate_paid_at
    OR NEW."redeemedAt" > certificate_expires_at
  THEN
    RAISE EXCEPTION 'GiftCertificateRedemption requires a paid, unexpired certificate'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_action_attempt_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  execution_row "ActionExecution"%ROWTYPE;
  expected_number INTEGER;
BEGIN
  SELECT * INTO execution_row
  FROM "ActionExecution"
  WHERE "id" = NEW."actionExecutionId"
    AND "tenantId" = NEW."tenantId"
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ActionAttempt execution is missing or cross-tenant'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(MAX("attemptNumber"), 0) + 1 INTO expected_number
  FROM "ActionAttempt"
  WHERE "tenantId" = NEW."tenantId"
    AND "actionExecutionId" = NEW."actionExecutionId";

  IF NEW."attemptNumber" <> expected_number THEN
    RAISE EXCEPTION 'ActionAttempt number must be the next durable sequence'
      USING ERRCODE = '23514';
  END IF;

  IF NEW."kind" = 'EXECUTION' AND execution_row."state" <> 'READY' THEN
    RAISE EXCEPTION 'Execution attempt requires READY ActionExecution'
      USING ERRCODE = '23514';
  END IF;

  IF NEW."kind" = 'RECONCILIATION' AND (
    execution_row."state" <> 'UNKNOWN'
    OR execution_row."reconciliationState" <> 'REQUIRED'
  ) THEN
    RAISE EXCEPTION 'Reconciliation attempt requires UNKNOWN/REQUIRED execution'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_action_target_mutation_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  expected_generation INTEGER;
BEGIN
  PERFORM "p5_require_governed_execution"(
    NEW."tenantId",
    NEW."actionExecutionId"
  );

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      NEW."tenantId"
        || ':p5:target:' || NEW."targetKind"
        || ':' || NEW."targetRef",
      0
    )
  );

  SELECT COALESCE(MAX("targetGeneration"), -1) + 1
  INTO expected_generation
  FROM "ActionTargetMutation"
  WHERE "tenantId" = NEW."tenantId"
    AND "targetKind" = NEW."targetKind"
    AND "targetRef" = NEW."targetRef";

  IF NEW."targetGeneration" <> expected_generation THEN
    RAISE EXCEPTION 'ActionTargetMutation generation must be the next contiguous target generation'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_ai_confirmation_activation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE receipt JSONB;
BEGIN
  SELECT "confirmationReceiptJson" INTO receipt FROM "AiOnboardingDraft"
    WHERE "trialActivationId"=OLD."id" AND "confirmationReceiptJson" IS NOT NULL;
  IF NOT FOUND THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Receipt activation cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['status','tenantId','completedAt','updatedAt']) IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['status','tenantId','completedAt','updatedAt'])
    OR NEW."status" NOT IN ('pending','completed')
    OR (OLD."status"='completed' AND (NEW."status"<>'completed'
      OR NEW."tenantId" IS DISTINCT FROM OLD."tenantId" OR NEW."completedAt" IS DISTINCT FROM OLD."completedAt"))
    OR (NEW."status"='pending' AND (NEW."tenantId" IS NOT NULL OR NEW."completedAt" IS NOT NULL))
    OR (NEW."status"='completed' AND (NEW."tenantId" IS DISTINCT FROM receipt->>'expectedTenantId' OR NEW."completedAt" IS NULL)) THEN
    RAISE EXCEPTION 'Receipt activation cannot be reset or rebound' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_ai_confirmation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE activation "TrialActivation"%ROWTYPE; token_digest TEXT; receipt JSONB;
  server_now TIMESTAMP(3) := (clock_timestamp() AT TIME ZONE 'UTC')::TIMESTAMP(3);
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."confirmationReceiptJson" IS NOT NULL THEN
      RAISE EXCEPTION 'Confirmed draft evidence cannot be deleted' USING ERRCODE='23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."confirmationReceiptJson" IS NOT NULL OR NEW."confirmationMaterialEncrypted" IS NOT NULL OR NEW."revision" <> 0 THEN
      RAISE EXCEPTION 'Draft must start without historical confirmation' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD."confirmationReceiptJson" IS NOT NULL THEN
    IF (to_jsonb(NEW) - ARRAY['status','confirmedTenantId','updatedAt']) IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['status','confirmedTenantId','updatedAt'])
       OR NEW."status" NOT IN ('confirming','confirmed')
       OR (OLD."status" = 'confirmed' AND NEW."status" <> 'confirmed')
       OR (OLD."confirmedTenantId" IS NOT NULL AND NEW."confirmedTenantId" IS DISTINCT FROM OLD."confirmedTenantId") THEN
      RAISE EXCEPTION 'Confirmation envelope is immutable; reset forbidden' USING ERRCODE='23514';
    END IF;
  ELSIF NEW."confirmationReceiptJson" IS NOT NULL THEN
    receipt := NEW."confirmationReceiptJson";
    SELECT * INTO activation FROM "TrialActivation" WHERE "id" = NEW."trialActivationId" FOR UPDATE;
    IF NOT FOUND OR activation."status" <> 'pending' OR activation."tenantId" IS NOT NULL
      OR activation."expiresAt" <= server_now OR OLD."expiresAt" <= server_now
      OR OLD."status" <> 'draft' OR NEW."status" <> 'confirming'
      OR NEW."trialActivationId" IS DISTINCT FROM OLD."trialActivationId"
      OR NEW."draftTokenHash" IS DISTINCT FROM OLD."draftTokenHash"
      OR NEW."expiresAt" IS DISTINCT FROM OLD."expiresAt"
      OR NEW."revision" <> OLD."revision"
      OR (receipt->>'draftRevision')::INTEGER <> OLD."revision"
      OR receipt->>'trialActivationId' IS DISTINCT FROM activation."id"
      OR receipt->>'draftSnapshotHash' IS DISTINCT FROM ai_confirmation_hash_v1(NEW."blueprintJson") THEN
      RAISE EXCEPTION 'Exact current draft and pending activation required' USING ERRCODE='23514';
    END IF;
    token_digest := encode(sha256(convert_to('package5.wave2.trial-bootstrap:' || activation."activationTokenHash", 'UTF8')), 'hex');
    IF receipt->>'expectedTenantId' IS DISTINCT FROM ('p5t_' || left(token_digest,28))
      OR receipt->>'ownerUserId' IS DISTINCT FROM ('p5o_' || left(token_digest,28))
      OR receipt->>'confirmationId' IS DISTINCT FROM ai_confirmation_hash_v1(jsonb_build_array(
        'package5.ai-draft-confirmation/1', NEW."id", OLD."revision", receipt->>'expectedTenantId',
        receipt->>'authorityHash', receipt->>'intentHash')) THEN
      RAISE EXCEPTION 'Reserved confirmation identity mismatch' USING ERRCODE='23514';
    END IF;
    NEW."confirmationReceiptJson" := jsonb_set(receipt, '{approvedAt}',
      to_jsonb(to_char(server_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  ELSE
    -- Old deployed writers remain compatible until runtime release; every edit
    -- advances the server revision. New callers additionally use revision CAS.
    IF NEW."revision" NOT IN (OLD."revision", OLD."revision" + 1) THEN
      RAISE EXCEPTION 'Draft revision cannot be rewritten' USING ERRCODE='23514';
    END IF;
    NEW."revision" := OLD."revision" + 1;
  END IF;
  IF NEW."confirmationReceiptJson" IS NOT NULL THEN
    IF NEW."status" = 'confirming' AND NEW."confirmedTenantId" IS NOT NULL THEN
      RAISE EXCEPTION 'Partial confirmation cannot claim completion' USING ERRCODE='23514';
    END IF;
    IF NEW."status" = 'confirmed' AND NOT EXISTS (
      SELECT 1 FROM "TrialActivation" a JOIN "Membership" m ON m."tenantId"=a."tenantId"
        AND m."userId"=NEW."confirmationReceiptJson"->>'ownerUserId'
      WHERE a."id"=NEW."trialActivationId" AND a."status"='completed'
        AND a."tenantId"=NEW."confirmedTenantId"
        AND a."tenantId"=NEW."confirmationReceiptJson"->>'expectedTenantId'
    ) THEN RAISE EXCEPTION 'Confirmation requires exact durable bootstrap result' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_b31_booking_intent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."bookingIntentContract" IS NOT NULL AND EXISTS (SELECT 1 FROM "Tenant" WHERE id = OLD."tenantId") THEN
      RAISE EXCEPTION 'B31 booking identity cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."bookingIntentContract" IS NOT NULL AND NEW."bookingIntentEncrypted" IS NULL THEN
      RAISE EXCEPTION 'B31 accepted intent requires encrypted snapshot' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  -- This also prevents installing an invented fingerprint on a legacy row.
  IF NEW."bookingIntentContract" IS DISTINCT FROM OLD."bookingIntentContract"
     OR NEW."bookingIntentHash" IS DISTINCT FROM OLD."bookingIntentHash"
     OR (OLD."bookingIntentContract" IS NOT NULL AND
       (NEW."tenantId", NEW.id, NEW."normalizedInputContract", NEW."normalizedInputHash", NEW."identityFingerprint",
        NEW."capability", NEW."actionClass", NEW."targetRef", NEW."transportIdempotencyKey") IS DISTINCT FROM
       (OLD."tenantId", OLD.id, OLD."normalizedInputContract", OLD."normalizedInputHash", OLD."identityFingerprint",
        OLD."capability", OLD."actionClass", OLD."targetRef", OLD."transportIdempotencyKey")) THEN
    RAISE EXCEPTION 'B31 accepted booking intent is immutable; no historical backfill' USING ERRCODE = '23514';
  END IF;
  IF NEW."bookingIntentEncrypted" IS DISTINCT FROM OLD."bookingIntentEncrypted"
     OR (OLD."bookingIntentContract" IS NOT NULL AND NEW."normalizedInputEncrypted" IS DISTINCT FROM OLD."normalizedInputEncrypted") THEN
    IF (NEW."bookingIntentEncrypted" IS DISTINCT FROM OLD."bookingIntentEncrypted" AND NEW."bookingIntentEncrypted" IS NOT NULL)
       OR (NEW."normalizedInputEncrypted" IS DISTINCT FROM OLD."normalizedInputEncrypted" AND NEW."normalizedInputEncrypted" IS NOT NULL)
       OR OLD."bookingIntentContract" IS NULL
       OR NEW.state::TEXT NOT IN ('SUCCEEDED', 'FAILED', 'NOT_EXECUTED')
       OR NEW."payloadRetentionUntil" IS NULL OR NEW."payloadRetentionUntil" > CURRENT_TIMESTAMP THEN
      RAISE EXCEPTION 'B31 snapshot permits only terminal retention cleanup' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_b31_idempotency_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE e "ActionExecution"%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM "Tenant" WHERE id = OLD."tenantId") THEN
      RAISE EXCEPTION 'B31 accepted binding cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'B31 accepted binding cannot be rebound' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  -- Serialize aliases on their durable owner as well as the unique caller key.
  SELECT * INTO e FROM "ActionExecution"
    WHERE id = NEW."actionExecutionId" AND "tenantId" = NEW."tenantId" FOR UPDATE;
  IF NOT FOUND OR e."bookingIntentContract" IS DISTINCT FROM 'maya.client-appointment-create-intent/1' THEN
    RAISE EXCEPTION 'B31 binding requires an existing canonical booking intent' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM "ActionExecutionIdempotencyBinding"
    WHERE "actionExecutionId" = e.id AND "tenantId" = e."tenantId" AND "clientId" <> NEW."clientId") THEN
    RAISE EXCEPTION 'B31 execution cannot bind a different Client' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_b33_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'B33 confirmation is immutable and cannot be deleted or rebound' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM "ClientChannelLink" l JOIN "Client" c ON c.id = l."clientId" AND c."tenantId" = l."tenantId"
    WHERE l.id = NEW."clientChannelLinkId" AND l."tenantId" = NEW."tenantId" AND l."clientId" = NEW."clientId"
      AND l."revokedAt" IS NULL AND l."verificationVersion" = 1 AND l."subjectHashVersion" = 1
      AND c."mergedIntoClientId" IS NULL FOR SHARE OF l, c;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'B33 requires an active verified canonical Client binding' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_client_channel_link_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prior_id TEXT;
  prior_revoked TIMESTAMP(3);
  latest_count INTEGER;
  verified_delivery_hash TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ClientChannelLink historical evidence cannot be deleted' USING ERRCODE = '23514';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    jsonb_build_array('a18.client-channel.v1', NEW."tenantId", NEW."provider", NEW."providerSubjectHash")::TEXT, 0));

  verified_delivery_hash := current_setting('maya.client_channel_delivery_subject_hash', true);

  IF TG_OP = 'UPDATE' THEN
    IF NEW."deliveryAddressEncrypted" IS DISTINCT FROM OLD."deliveryAddressEncrypted"
       AND (to_jsonb(NEW) - 'deliveryAddressEncrypted') =
           (to_jsonb(OLD) - 'deliveryAddressEncrypted')
    THEN
      IF OLD."revokedAt" IS NOT NULL OR NEW."deliveryAddressEncrypted" IS NULL
         OR verified_delivery_hash IS DISTINCT FROM OLD."providerSubjectHash"
      THEN
        RAISE EXCEPTION 'ClientChannelLink delivery address requires the matching active verified channel' USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END IF;

    IF (to_jsonb(NEW) - ARRAY['revokedAt', 'revocationIdentityHash', 'revocationEvidenceJson', 'revocationEvidenceHash'])
       IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['revokedAt', 'revocationIdentityHash', 'revocationEvidenceJson', 'revocationEvidenceHash'])
      OR OLD."revokedAt" IS NOT NULL OR NEW."revokedAt" IS NULL
    THEN
      RAISE EXCEPTION 'ClientChannelLink permits only verified delivery rotation or first complete revocation; original evidence is immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW."revokedAt" > (clock_timestamp() AT TIME ZONE 'UTC')::TIMESTAMP(3) THEN
      RAISE EXCEPTION 'ClientChannelLink revocation cannot be future-dated' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW."deliveryAddressEncrypted" IS NOT NULL
     AND verified_delivery_hash IS DISTINCT FROM NEW."providerSubjectHash"
  THEN
    RAISE EXCEPTION 'ClientChannelLink delivery address requires the matching verified channel' USING ERRCODE = '23514';
  END IF;
  IF NEW."revokedAt" IS NOT NULL OR NEW."createdAt" > (clock_timestamp() AT TIME ZONE 'UTC')::TIMESTAMP(3)
     OR NEW."verifiedAt" > (clock_timestamp() AT TIME ZONE 'UTC')::TIMESTAMP(3) THEN
    RAISE EXCEPTION 'ClientChannelLink must start as a currently verified episode' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM "Client" WHERE "id" = NEW."clientId" AND "tenantId" = NEW."tenantId"
    AND "mergedIntoClientId" IS NULL FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ClientChannelLink requires an exact unmerged tenant Client' USING ERRCODE = '23514';
  END IF;

  SELECT count(*) INTO latest_count FROM "ClientChannelLink" p
    WHERE p."tenantId" = NEW."tenantId" AND p."provider" = NEW."provider"
      AND p."providerSubjectHash" = NEW."providerSubjectHash"
      AND NOT EXISTS (SELECT 1 FROM "ClientChannelLink" s WHERE s."supersedesLinkId" = p."id");
  IF latest_count = 0 THEN
    IF NEW."supersedesLinkId" IS NOT NULL THEN
      RAISE EXCEPTION 'Initial ClientChannelLink cannot claim a predecessor' USING ERRCODE = '23514';
    END IF;
  ELSIF latest_count = 1 THEN
    SELECT p."id", p."revokedAt" INTO prior_id, prior_revoked FROM "ClientChannelLink" p
      WHERE p."tenantId" = NEW."tenantId" AND p."provider" = NEW."provider"
        AND p."providerSubjectHash" = NEW."providerSubjectHash"
        AND NOT EXISTS (SELECT 1 FROM "ClientChannelLink" s WHERE s."supersedesLinkId" = p."id");
    IF NEW."supersedesLinkId" IS DISTINCT FROM prior_id OR prior_revoked IS NULL THEN
      RAISE EXCEPTION 'ClientChannelLink re-link requires the latest explicitly revoked predecessor' USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'Ambiguous ClientChannelLink history requires explicit repair' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_client_consent_fact_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW."actionExecutionId" IS NOT NULL THEN
    PERFORM "p5_require_governed_execution"(
      NEW."tenantId",
      NEW."actionExecutionId"
    );
  END IF;
  RETURN NEW;
