$function$

CREATE OR REPLACE FUNCTION public.guard_client_link_challenge_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE server_now TIMESTAMP(3) := (clock_timestamp() AT TIME ZONE 'UTC')::TIMESTAMP(3);
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ClientLinkChallenge evidence cleanup is not authorized' USING ERRCODE = '23514';
  END IF;
  IF NEW."issuedAt" > server_now OR NEW."expiresAt" <> NEW."issuedAt" + INTERVAL '600 seconds' THEN
    RAISE EXCEPTION 'ClientLinkChallenge requires server time and exact TTL V1' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM "Client" WHERE "id" = NEW."clientId" AND "tenantId" = NEW."tenantId"
    AND "mergedIntoClientId" IS NULL FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ClientLinkChallenge requires exact unmerged tenant Client' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."consumedAt" IS NOT NULL OR NEW."consumedLinkId" IS NOT NULL OR NEW."consumedProvider" IS NOT NULL OR NEW."consumedSubjectHash" IS NOT NULL THEN
      RAISE EXCEPTION 'ClientLinkChallenge must start unconsumed' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF (to_jsonb(NEW) - ARRAY['consumedAt', 'consumedLinkId', 'consumedProvider', 'consumedSubjectHash']) IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['consumedAt', 'consumedLinkId', 'consumedProvider', 'consumedSubjectHash'])
       OR OLD."consumedAt" IS NOT NULL OR NEW."consumedAt" IS NULL THEN
      RAISE EXCEPTION 'ClientLinkChallenge permits first consume only; issuance evidence is immutable' USING ERRCODE = '23514';
    END IF;
    IF server_now >= NEW."expiresAt" THEN
      RAISE EXCEPTION 'ClientLinkChallenge expired at actual consume time' USING ERRCODE = '23514';
    END IF;
    NEW."consumedAt" := server_now;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_client_wanted_slot_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE active_count INTEGER;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW."tenantId" || ':wanted-slot:' || NEW."clientId", 0));
  NEW."expiresAt" := NEW."desiredStartAt";
  NEW."matchToleranceMinutes" := 0;
  NEW."status" := 'ACTIVE';
  NEW."createdAt" := timezone('UTC'::text, CURRENT_TIMESTAMP);
  NEW."updatedAt" := NEW."createdAt";
  NEW."matchedSourceEventId" := NULL;
  NEW."matchedAt" := NULL;
  NEW."notifiedAt" := NULL;
  NEW."terminalAt" := NULL;
  NEW."lastMutationActionExecutionId" := NULL;
  IF NEW."desiredStartAt" <= timezone('UTC'::text, CURRENT_TIMESTAMP) THEN
    RAISE EXCEPTION 'Wanted slot must be in the future';
  END IF;
  SELECT count(*) INTO active_count FROM "ClientWantedSlotInterest"
    WHERE "tenantId" = NEW."tenantId" AND "clientId" = NEW."clientId" AND "status" = 'ACTIVE';
  IF active_count >= 10 THEN
    RAISE EXCEPTION 'CLIENT_WANTED_SLOT_LIMIT_EXCEEDED';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_client_wanted_slot_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE eligible_ids TEXT;
BEGIN
  IF NEW."tenantId" IS DISTINCT FROM OLD."tenantId"
    OR NEW."clientId" IS DISTINCT FROM OLD."clientId"
    OR NEW."branchId" IS DISTINCT FROM OLD."branchId"
    OR NEW."staffId" IS DISTINCT FROM OLD."staffId"
    OR NEW."desiredStartAt" IS DISTINCT FROM OLD."desiredStartAt"
    OR NEW."expiresAt" IS DISTINCT FROM OLD."expiresAt"
    OR NEW."matchToleranceMinutes" IS DISTINCT FROM OLD."matchToleranceMinutes"
    OR NEW."createdByActionExecutionId" IS DISTINCT FROM OLD."createdByActionExecutionId"
    OR NEW."sourceChannelLinkId" IS DISTINCT FROM OLD."sourceChannelLinkId"
    OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" THEN
    RAISE EXCEPTION 'Wanted slot historical request facts are immutable';
  END IF;
  IF OLD."status" <> NEW."status" AND NOT (
    (OLD."status" = 'ACTIVE' AND NEW."status" IN ('MATCHED', 'CANCELLED', 'EXPIRED'))
    OR (OLD."status" = 'MATCHED' AND NEW."status" IN ('NOTIFIED', 'CANCELLED'))
  ) THEN RAISE EXCEPTION 'Invalid wanted slot lifecycle transition'; END IF;
  IF OLD."matchedSourceEventId" IS NOT NULL AND NEW."matchedSourceEventId" IS DISTINCT FROM OLD."matchedSourceEventId" THEN
    RAISE EXCEPTION 'Wanted slot match source is immutable';
  END IF;
  IF OLD."matchedAt" IS NOT NULL AND NEW."matchedAt" IS DISTINCT FROM OLD."matchedAt" THEN
    RAISE EXCEPTION 'Wanted slot match time is immutable';
  END IF;
  IF OLD."notifiedAt" IS NOT NULL AND NEW."notifiedAt" IS DISTINCT FROM OLD."notifiedAt" THEN
    RAISE EXCEPTION 'Wanted slot notification time is immutable';
  END IF;
  IF OLD."terminalAt" IS NOT NULL AND NEW."terminalAt" IS DISTINCT FROM OLD."terminalAt" THEN
    RAISE EXCEPTION 'Wanted slot terminal time is immutable';
  END IF;
  IF NEW."status" = 'EXPIRED' AND timezone('UTC'::text, CURRENT_TIMESTAMP) < NEW."expiresAt" THEN
    RAISE EXCEPTION 'Wanted slot cannot expire before requested start';
  END IF;
  IF NEW."status" = 'MATCHED' AND OLD."status" = 'ACTIVE' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(NEW."tenantId" || ':wanted-slot-event:' || NEW."matchedSourceEventId", 0));
    eligible_ids := current_setting('maya.client_wanted_slot_eligible_ids', true);
    IF eligible_ids IS NULL
      OR NOT (',' || eligible_ids || ',' LIKE '%,' || NEW."id" || ',%')
      OR array_length(string_to_array(eligible_ids, ','), 1) > 3 THEN
      RAISE EXCEPTION 'Wanted slot match requires canonical eligible ordering';
    END IF;
    IF EXISTS (
      SELECT 1 FROM "ClientWantedSlotInterest" earlier
      WHERE earlier."tenantId" = NEW."tenantId"
        AND earlier."branchId" = NEW."branchId"
        AND earlier."staffId" = NEW."staffId"
        AND earlier."desiredStartAt" = NEW."desiredStartAt"
        AND earlier."status" = 'ACTIVE'
        AND (earlier."createdAt", earlier."id") < (NEW."createdAt", NEW."id")
        AND ',' || eligible_ids || ',' LIKE '%,' || earlier."id" || ',%'
    ) THEN RAISE EXCEPTION 'Wanted slot matching must use earliest eligible ordering'; END IF;
    IF (SELECT count(*) FROM "ClientWantedSlotInterest" matched
        WHERE matched."tenantId" = NEW."tenantId"
          AND matched."matchedSourceEventId" = NEW."matchedSourceEventId") >= 3 THEN
      RAISE EXCEPTION 'WANTED_SLOT_MATCH_FAN_OUT_EXCEEDED';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_client_web_push_endpoint_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  verified_link TEXT;
  verified_owner TEXT;
  evidence_hash TEXT;
  active_count INTEGER;
  previous "ClientWebPushEndpoint"%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'WEB_PUSH_HISTORY_IMMUTABLE' USING ERRCODE = '23514';
  END IF;
  -- Global endpoint identity prevents cross-tenant ownership collisions.
  PERFORM pg_advisory_xact_lock(hashtextextended('b24.endpoint:' || NEW."endpointHash", 0));
  PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array('b24.client', NEW."tenantId", NEW."clientId")::TEXT, 0));
  IF TG_OP = 'UPDATE' THEN
    IF OLD."endedAt" IS NOT NULL OR NEW."endedAt" IS NULL
       OR (to_jsonb(NEW) - ARRAY['endedAt','endReason','terminationIdentityHash','terminationEvidenceJson','terminationEvidenceHash'])
          IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['endedAt','endReason','terminationIdentityHash','terminationEvidenceJson','terminationEvidenceHash'])
       OR current_setting('maya.web_push.termination_identity', true) IS DISTINCT FROM NEW."terminationIdentityHash"
    THEN RAISE EXCEPTION 'WEB_PUSH_ONLY_VERIFIED_TERMINAL_TRANSITION' USING ERRCODE = '23514'; END IF;
    NEW."endedAt" := (clock_timestamp() AT TIME ZONE 'UTC')::TIMESTAMP(3);
    RETURN NEW;
  END IF;
  IF NEW."endedAt" IS NOT NULL THEN
    RAISE EXCEPTION 'WEB_PUSH_NEW_EPISODE_MUST_BE_ACTIVE' USING ERRCODE = '23514';
  END IF;
  verified_link := current_setting('maya.web_push.verified_link', true);
  verified_owner := current_setting('maya.web_push.verified_client', true);
  IF verified_link IS DISTINCT FROM NEW."clientChannelLinkId"
     OR verified_owner IS DISTINCT FROM NEW."clientId" THEN
    RAISE EXCEPTION 'WEB_PUSH_VERIFIED_CLIENT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  SELECT l."verificationEvidenceHash" INTO evidence_hash
    FROM "ClientChannelLink" l JOIN "Client" c ON c."id"=l."clientId" AND c."tenantId"=l."tenantId"
    WHERE l."id"=NEW."clientChannelLinkId" AND l."tenantId"=NEW."tenantId" AND l."clientId"=NEW."clientId"
      AND l."revokedAt" IS NULL AND l."verificationVersion"=1 AND l."subjectHashVersion"=1
      AND c."mergedIntoClientId" IS NULL FOR SHARE OF l, c;
  IF evidence_hash IS NULL OR evidence_hash IS DISTINCT FROM NEW."registrationEvidenceJson"->>'linkEvidenceHash' THEN
    RAISE EXCEPTION 'WEB_PUSH_ACTIVE_VERIFIED_LINK_REQUIRED' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM "ClientWebPushEndpoint" e WHERE e."endpointHash"=NEW."endpointHash"
      AND (e."tenantId"<>NEW."tenantId" OR e."clientId"<>NEW."clientId")) THEN
    RAISE EXCEPTION 'WEB_PUSH_ENDPOINT_OWNERSHIP_CONFLICT' USING ERRCODE = '23514';
  END IF;
  IF NEW."supersedesEndpointId" IS NOT NULL THEN
    SELECT * INTO previous FROM "ClientWebPushEndpoint" WHERE "id"=NEW."supersedesEndpointId";
    IF previous."id" IS NULL OR previous."tenantId"<>NEW."tenantId" OR previous."clientId"<>NEW."clientId"
      OR previous."endedAt" IS NULL OR previous."endReason"<>'REPLACED' THEN
      RAISE EXCEPTION 'WEB_PUSH_EXPLICIT_REPLACEMENT_REQUIRED' USING ERRCODE = '23514';
    END IF;
  ELSIF EXISTS (SELECT 1 FROM "ClientWebPushEndpoint" WHERE "endpointHash"=NEW."endpointHash") THEN
    RAISE EXCEPTION 'WEB_PUSH_NO_IMPLICIT_RESURRECTION' USING ERRCODE = '23514';
  END IF;
  SELECT count(*) INTO active_count FROM "ClientWebPushEndpoint"
    WHERE "tenantId"=NEW."tenantId" AND "clientId"=NEW."clientId" AND "endedAt" IS NULL;
  IF active_count >= 5 THEN
    RAISE EXCEPTION 'CLIENT_WEB_PUSH_LIMIT_EXCEEDED' USING ERRCODE = '23514';
  END IF;
  NEW."createdAt" := (clock_timestamp() AT TIME ZONE 'UTC')::TIMESTAMP(3);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_expense_period_declaration_epoch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  expected_epoch INTEGER;
  execution_action_class TEXT;
  execution_state TEXT;
  execution_policy TEXT;
  execution_dry_run BOOLEAN;
  execution_target_kind TEXT;
  execution_target_ref TEXT;
BEGIN
  IF TG_OP = 'UPDATE'
    AND OLD."declarationEpoch" IS NOT NULL
    AND (
      NEW."declarationEpoch" IS DISTINCT FROM OLD."declarationEpoch"
      OR NEW."tenantId" IS DISTINCT FROM OLD."tenantId"
      OR NEW."periodFromDay" IS DISTINCT FROM OLD."periodFromDay"
      OR NEW."periodToDay" IS DISTINCT FROM OLD."periodToDay"
      OR NEW."actionExecutionId" IS DISTINCT FROM OLD."actionExecutionId"
    )
  THEN
    RAISE EXCEPTION 'Established ExpensePeriodDeclaration epoch binding is immutable'
      USING ERRCODE = '23514';
  END IF;

  IF NEW."declarationEpoch" IS NULL THEN
    IF (
      TG_OP = 'INSERT'
      AND NEW."actionExecutionId" IS NOT NULL
    ) OR (
      TG_OP = 'UPDATE'
      AND OLD."actionExecutionId" IS NULL
      AND NEW."actionExecutionId" IS NOT NULL
    )
    THEN
      RAISE EXCEPTION 'New canonical ExpensePeriodDeclaration requires declarationEpoch'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW."tenantId" || ':expense-ledger', 0)
  );

  SELECT COALESCE(MAX("nextDeclarationEpoch"), 0)
  INTO expected_epoch
  FROM "ExpensePeriodDeclarationInvalidation"
  WHERE "tenantId" = NEW."tenantId"
    AND "periodFromDay" = NEW."periodFromDay"
    AND "periodToDay" = NEW."periodToDay";

  IF NEW."declarationEpoch" IS DISTINCT FROM expected_epoch THEN
    RAISE EXCEPTION 'ExpensePeriodDeclaration epoch is stale or forged'
      USING ERRCODE = '23514';
  END IF;

  IF NEW."actionExecutionId" IS NULL THEN
    RAISE EXCEPTION 'Canonical ExpensePeriodDeclaration requires ActionExecution binding'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    "actionClass",
    "state"::TEXT,
    "policyDecision"::TEXT,
    "dryRun",
    "targetKind",
    "targetRef"
  INTO
    execution_action_class,
    execution_state,
    execution_policy,
    execution_dry_run,
    execution_target_kind,
    execution_target_ref
  FROM "ActionExecution"
  WHERE "id" = NEW."actionExecutionId"
    AND "tenantId" = NEW."tenantId"
  FOR KEY SHARE;

  IF NOT FOUND
    OR execution_action_class <> 'declare_expense_period_complete'
    OR execution_state NOT IN ('EXECUTING', 'SUCCEEDED')
    OR execution_policy <> 'ALLOW'
    OR execution_dry_run
    OR execution_target_kind <> 'expense_period'
    OR execution_target_ref <> (
      'expense-period:' || NEW."periodFromDay" || ':' || NEW."periodToDay"
    )
  THEN
    RAISE EXCEPTION 'ExpensePeriodDeclaration epoch requires its exact canonical execution'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM "ExpensePeriodDeclarationInvalidation"
    WHERE "tenantId" = NEW."tenantId"
      AND "invalidatedDeclarationActionExecutionId" = NEW."actionExecutionId"
  )
  THEN
    RAISE EXCEPTION 'Invalidated declaration execution cannot be rebound to a later epoch'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_maintenance_run_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW."scope" = 'tenant' THEN
    IF NEW."requestedByUserId" IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM "Membership"
      WHERE "tenantId" = NEW."tenantId"
        AND "userId" = NEW."requestedByUserId"
    ) THEN
      RAISE EXCEPTION 'Tenant maintenance requester must be an exact tenant member'
        USING ERRCODE = '23514';
    END IF;

    IF NEW."approvedByUserId" IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM "Membership"
      WHERE "tenantId" = NEW."tenantId"
        AND "userId" = NEW."approvedByUserId"
    ) THEN
      RAISE EXCEPTION 'Tenant maintenance approver must be an exact tenant member'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    IF NEW."requestedByUserId" IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM "User"
      WHERE "id" = NEW."requestedByUserId"
        AND "role"::TEXT IN ('platform_owner', 'platform_admin')
    ) THEN
      RAISE EXCEPTION 'Platform maintenance requester must have platform authority'
        USING ERRCODE = '23514';
    END IF;

    IF NEW."approvedByUserId" IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM "User"
      WHERE "id" = NEW."approvedByUserId"
        AND "role"::TEXT IN ('platform_owner', 'platform_admin')
    ) THEN
      RAISE EXCEPTION 'Platform maintenance approver must have platform authority'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW."actionExecutionId" IS NOT NULL THEN
    PERFORM "p5_require_governed_execution"(
      NEW."tenantId",
      NEW."actionExecutionId"
    );
  END IF;

  RETURN NEW;
END;
$function$

